const REPO_CLIENT_DIR = join("🧰️framework", "🛍️products", "🦑️repo", "🔨️modules", "💻️client");
const REPO_CLIENT_GO = join(REPO_CLIENT_DIR, "⌨️cli");
const REPO_MCP_GO = join(REPO_CLIENT_DIR, "🔌️mcp");
process.env.NX_ISOLATE_PLUGINS = "false";

/** 🦑️Builds the repo MCP client from the current source before execution. */
function buildRepoMcpClient(root: string): string {
  const bin = resolveCliBin(root);
  runCmd("go", ["build", "-o", bin, `./${REPO_MCP_GO}`], {
    cwd: root,
    env: { ...process.env, GOWORK: join(root, "go.work") },
    budgetMs: buildBudgetMs(),
  });
  return bin;
}

export { Script };

function ensureFrameworkOsPlaygroundCatalog() {
  let catalog = loadFrameworkOsPlaygroundCatalog();
  if (catalog.length > 0) return catalog;
  runCmdStatus("bun", ["nx", "run", "@semio-tech/plugin-registry:generate"], { cwd: WORKSPACE_ROOT, ...orchestratorBudgetOpts() });
  catalog = loadFrameworkOsPlaygroundCatalog();
  if (catalog.length === 0) {
    console.error("[dev] playground catalog is empty after registry generate — check @semio-tech/plugin-registry.");
    process.exit(1);
  }
  return catalog;
}

function resolvePlaygroundDevApp(segments: string[]): { readonly app: string; readonly rest: string[] } | null {
  const resolved = resolveFrameworkOsPlaygroundPlugin(ensureFrameworkOsPlaygroundCatalog(), segments);
  if (!resolved) return null;
  return { app: resolved.plugin, rest: [...resolved.rest] };
}

/** 🍽️ `served` boots the REACT OS shell over Vite against whatever `🔌️plugin-modules/` already
 * holds, skipping the ~59-crate plugin build — the exact `SEMIO_RENDERER=react` +
 * `SKIP_PLUGIN_BUILD=1` pair `collabStartUserDevServer` spawns each collab user with.
 *
 * Both halves are load-bearing. `frameworkOsPlaygroundDevEnv` defaults `SEMIO_RENDERER` to `wgpu`,
 * so a bare `dev s` builds all 59 crates and then hands off to `trunk serve`, never to Vite on
 * `S_OS_PORT`; and streaming plugin builds are gated on `renderer === "react"`, so the skip only
 * takes effect once react is selected.
 *
 * It is a command segment rather than an env var so it stays reachable from `launch.json`, which is
 * how every dev here starts things and which carries no `env` field. */
function runFrameworkOsPlaygroundDev(plugin: string, rest: string[] = []): void {
  const served = rest.includes("served");
  const args = rest.filter((segment) => segment !== "served");
  runCmd("bun", ["nx", "run", "@semio-tech/framework-os-dev:dev", "--", plugin, ...args], {
    cwd: WORKSPACE_ROOT,
    env: frameworkOsPlaygroundDevEnv(ensureFrameworkOsPlaygroundCatalog(), plugin, served ? { SEMIO_RENDERER: "react", SKIP_PLUGIN_BUILD: "1" } : {}),
    ...daemonBudgetOpts(),
  });
}

//#region 🔖️NativeOsScript
/** 🖥️Runs native bootstrap shells under `repo/native/bootstrap` (setup|start). */
export class NativeOsScript extends Script {
  run(segments: string[]): void {
    const cmd = segments[0] ?? "setup";
    const env = { ...process.env };
    if (process.platform === "win32") {
      const ps1 = join(NATIVE_BOOTSTRAP_DIR, "🔵️.ps1");
      if (!existsSync(ps1)) {
        console.error(`[native] missing ${ps1}; expected repo/native/bootstrap/🔵️.ps1.`);
        process.exit(1);
      }
      runCmd("powershell.exe", ["-NoProfile", "-ExecutionPolicy", "Bypass", "-File", ps1, cmd], { cwd: this.root, env });
      return;
    }
    if (process.platform === "darwin" || process.platform === "linux") {
      const sh = join(NATIVE_BOOTSTRAP_DIR, "🐚️.sh");
      if (!existsSync(sh)) {
        console.error(`[native] missing ${sh}; expected repo/native/bootstrap/🐚️.sh.`);
        process.exit(1);
      }
      runCmd("bash", [sh, cmd], { cwd: this.root, env });
      return;
    }
    console.error(`[native] unsupported platform ${process.platform}`);
    process.exit(1);
  }
}
//#endregion 🔖️NativeOsScript

//#region 🔖️SccacheSetup
const SCCACHE_VERSION = "0.10.0";

/** ⚡️Ensures `sccache` is on PATH for `.cargo/config.toml` rustc-wrapper. */
function ensureSccache(): void {
  try {
    if (runProbe("sccache", ["--version"]).status === 0) return;
  } catch {
    /* install below */
  }

  const asset = sccacheReleaseAsset();
  if (!asset) {
    console.warn("[setup] sccache auto-install unsupported on this platform; install manually.");
    return;
  }

  const binDir = process.platform === "win32" ? join(process.env.LOCALAPPDATA ?? join(homedir(), "AppData", "Local"), "bin") : join(homedir(), ".local", "bin");
  const binName = process.platform === "win32" ? "sccache.exe" : "sccache";
  const dest = join(binDir, binName);
  if (existsSync(dest)) return;

  const cacheDir = join(getRepoMetaDir(WORKSPACE_ROOT), "⚡️cache", "sccache");
  mkdirSync(cacheDir, { recursive: true });
  const archive = join(cacheDir, asset);
  const url = `https://github.com/mozilla/sccache/releases/download/v${SCCACHE_VERSION}/${asset}`;
  console.log(`[setup] downloading sccache ${SCCACHE_VERSION}…`);
  runCmd("curl", ["-fSL", "-o", archive, url]);

  if (asset.endsWith(".tar.gz")) {
    runCmd("tar", ["-xzf", archive, "-C", cacheDir]);
    const extractedDir = readdirSync(cacheDir).find((name) => name.startsWith("sccache-") && !name.endsWith(".tar.gz"));
    if (!extractedDir) throw new Error("sccache archive extraction failed");
    copyFileSync(join(cacheDir, extractedDir, binName), dest);
  } else {
    const extractDir = join(cacheDir, "extract");
    rmSync(extractDir, { recursive: true, force: true });
    mkdirSync(extractDir, { recursive: true });
    if (process.platform === "win32") {
      runCmd("powershell.exe", ["-NoProfile", "-Command", `Expand-Archive -Path '${archive}' -DestinationPath '${extractDir}' -Force`]);
    } else {
      runCmd("unzip", ["-o", archive, "-d", extractDir]);
    }
    const extractedDir = readdirSync(extractDir).find((name) => name.startsWith("sccache-"));
    if (!extractedDir) throw new Error("sccache archive extraction failed");
    copyFileSync(join(extractDir, extractedDir, binName), dest);
  }

  if (process.platform !== "win32") chmodSync(dest, 0o755);
  console.log(`[setup] installed sccache -> ${dest}`);
}

function sccacheReleaseAsset(): string | null {
  if (process.platform === "darwin") {
    return process.arch === "arm64" ? `sccache-v${SCCACHE_VERSION}-aarch64-apple-darwin.tar.gz` : `sccache-v${SCCACHE_VERSION}-x86_64-apple-darwin.tar.gz`;
  }
  if (process.platform === "linux") {
    const report = process.report?.getReport?.() as { header?: { glibcVersionRuntime?: string } } | undefined;
    const libc = report?.header?.glibcVersionRuntime ? "gnu" : "musl";
    return process.arch === "arm64" ? `sccache-v${SCCACHE_VERSION}-aarch64-unknown-linux-${libc}.tar.gz` : `sccache-v${SCCACHE_VERSION}-x86_64-unknown-linux-${libc}.tar.gz`;
  }
  if (process.platform === "win32") {
    return process.arch === "arm64" ? `sccache-v${SCCACHE_VERSION}-aarch64-pc-windows-msvc.zip` : `sccache-v${SCCACHE_VERSION}-x86_64-pc-windows-msvc.zip`;
  }
  return null;
}
//#endregion 🔖️SccacheSetup

//#region 🔖️SetupScript
export class SetupScript extends Script {
  run(segments: string[]): void {
    if (!segments[0]) {
      this.runFull();
      return;
    }
    dispatchSubcommand(
      segments,
      {
        postinstall: () => this.runPostinstall(),
        git: () => this.runGit(),
        native: (rest) => new NativeOsScript(this.root).run(rest),
      },
      "bun ./📜️script.ts setup [postinstall|git|native]",
    );
  }

  private runPostinstall(): void {
    const pkgPath = join(this.root, "node_modules", "lightningcss", "package.json");
    if (!existsSync(pkgPath)) return;
    const { version } = JSON.parse(readFileSync(pkgPath, "utf8")) as { version: string };
    const report = process.report?.getReport?.() as { header?: { glibcVersionRuntime?: string } } | undefined;
    const libc = process.platform === "linux" ? (report?.header?.glibcVersionRuntime ? "gnu" : "musl") : "";
    const key = [process.platform, process.arch, libc].filter(Boolean).join("/");
    const pkgByKey: Record<string, string> = {
      "win32/x64": "lightningcss-win32-x64-msvc",
      "win32/arm64": "lightningcss-win32-arm64-msvc",
      "darwin/x64": "lightningcss-darwin-x64",
      "darwin/arm64": "lightningcss-darwin-arm64",
      "linux/x64/gnu": "lightningcss-linux-x64-gnu",
      "linux/x64/musl": "lightningcss-linux-x64-musl",
      "linux/arm64/gnu": "lightningcss-linux-arm64-gnu",
      "linux/arm64/musl": "lightningcss-linux-arm64-musl",
    };
    const platformPkg = pkgByKey[key];
    if (!platformPkg) return;
    if (existsSync(join(this.root, "node_modules", platformPkg))) return;
    runCmd("bun", ["add", "--no-save", `${platformPkg}@${version}`], { cwd: this.root });
  }

  private runGit(): void {
    runCmd("git", ["config", "--local", "core.symlinks", "true"], { cwd: this.root });
    const repoClientPath = buildRepoMcpClient(this.root);
    runCmd(repoClientPath, ["configure"], { cwd: this.root });
    installMicroCommitGitHooks(this.root);
    const source = "AGENTS.md";
    for (const alias of ["CLAUDE.md", "GEMINI.md"]) {
      const aliasPath = join(this.root, alias);
      if (existsSync(aliasPath)) rmSync(aliasPath, { force: true });
      try {
        symlinkSync(source, aliasPath, "file");
      } catch (error) {
        if (process.platform !== "win32") throw error;
        linkSync(join(this.root, source), aliasPath);
      }
    }
  }

  private runWorkspaceCodegen(): void {
    console.log("[setup] workspace codegen…");
    const opts = { cwd: this.root, ...orchestratorBudgetOpts() };
    const nx = join(this.root, "node_modules", "nx", "bin", "nx.js");
    const runNx = (target: string) => runCmd("node", [nx, "run", target], opts);
    runNx("@semio-tech/framework-schema:generate");
    runNx("@semio-tech/ui-styling-tokens:generate");
    runCmd("bun", ["./📜️script.ts", "build"], {
      cwd: join(this.root, "🧰️framework/🔨️modules/🖼️assets/📦️packages/🟦️typescript"),
      ...orchestratorBudgetOpts(),
    });
    runNx("@semio-tech/graph-manifest:generate");
    runNx("@semio-tech/plugin-registry:generate");
  }

  private runFull(): void {
    if (process.argv.includes("--with-native-os")) {
      console.log(`[setup] ${process.platform} native bootstrap…`);
      tryRun(BUN, [join(this.root, "📜️script.ts"), "setup", "native"], { cwd: this.root });
    }

    console.log("[setup] uv sync…");
    tryRun("uv", ["sync", "--all-packages", "--all-groups"]);
    console.log("[setup] neo4j MCP server prefetch (uvx)…");
    tryRun("uvx", ["--quiet", "mcp-neo4j-cypher", "--help"]);
    console.log("[setup] cargo fetch…");
    tryRun("cargo", ["fetch", "--manifest-path", "Cargo.toml"]);
    console.log("[setup] cargo-nextest…");
    tryRun("cargo", ["install", "cargo-nextest", "--locked"]);
    console.log("[setup] C++ toolchain and vcpkg…");
    tryRun("bun", [join(this.root, "📜️script.ts"), "cpp", "setup"], { cwd: this.root });
    console.log("[setup] go build repo client…");
    const clientOut = resolveCliBin(this.root);
    tryRun("go", ["build", "-o", clientOut, `./${REPO_MCP_GO}`], { env: { ...process.env, GOWORK: join(this.root, "go.work") } });
    console.log("[setup] dotnet restore…");
    tryRun("dotnet", ["restore", "Monorepo.sln"]);
    console.log("[setup] rustup wasm target…");
    tryRun("rustup", ["target", "add", "wasm32-unknown-unknown"]);
    console.log("[setup] cargo-llvm-cov (exhaustive-level coverage)…");
    tryRun("cargo", ["install", "cargo-llvm-cov", "--locked"]);
    console.log("[setup] sccache…");
    try {
      ensureSccache();
    } catch (error) {
      console.warn("[setup] sccache install skipped:", error);
    }

    const browsersPath = join(this.root, "node_modules", ".cache", "ms-playwright");
    mkdirSync(browsersPath, { recursive: true });
    console.log("[setup] Playwright browsers…");
    tryRun("bunx", ["playwright", "install", "--with-deps", "chromium"], {
      env: { ...process.env, PLAYWRIGHT_BROWSERS_PATH: browsersPath },
    });

    if (process.platform === "linux") {
      const chromeSandbox = join(this.root, "node_modules", "electron", "dist", "chrome-sandbox");
      if (existsSync(chromeSandbox)) {
        try {
          chownSync(chromeSandbox, 0, 0);
          chmodSync(chromeSandbox, 0o4755);
          console.log("[setup] Electron chrome-sandbox permissions set.");
        } catch (e) {
          console.warn("[setup] chrome-sandbox chmod skipped:", e);
        }
      }
    }

    console.log("[setup] git workspace (symlinks, hook cleanup)…");
    new SetupScript(this.root).run(["git"]);

    this.runWorkspaceCodegen();

    console.log("[setup] VS Code extension build & package…");
    tryRun("bun", ["nx", "run", "@semio-tech/repo-vscode:build"], { cwd: this.root });
    tryRun("bun", ["nx", "run", "@semio-tech/repo-vscode:build-vsix"], { cwd: this.root });
    console.log("[setup] done.");
  }
}
//#endregion 🔖️SetupScript

//#region 🔖️StartScript
export class StartScript extends Script {
  run(_segments: string[]): void {
    process.chdir(this.root);
    const runGenerate = () => {
      if (runCmdStatus(BUN, [join(this.root, "📜️script.ts"), "generate"], { cwd: this.root, ...orchestratorBudgetOpts() }) !== 0) {
        console.log("[start] `bun run generate` did not refresh all `.🧬semio/🦑️repo/🛂️manifest` bundles (Neo4j may be offline).");
      }
    };

    if (!existsSync(join(this.root, "node_modules", "nx", "package.json"))) {
      console.log("[start] node_modules incomplete — run `bun install` and `bun ./📜️script.ts setup`.");
      return;
    }

    if (process.env.DEVCONTAINER === "true") {
      runGenerate();
      console.log("[start] Devcontainer session ready.");
      return;
    }

    if (process.platform === "win32" || process.platform === "darwin" || process.platform === "linux") {
      new NativeOsScript(this.root).run(["start"]);
    } else {
      console.log(`[start] Unsupported platform ${process.platform}.`);
    }
    runGenerate();
  }
}
//#endregion 🔖️StartScript

//#region 🔖️DevScript
export class DevScript extends Script {
  async run(segments: string[]): Promise<void> {
    if (segments[0] === "storybook") {
      await this.runStorybook(segments.slice(1));
      return;
    }
    if (segments[0] === "storybook-static") {
      await this.runStorybookStatic();
      return;
    }
    if (segments[0] === "s") {
      runFrameworkOsPlaygroundDev("s", segments.slice(1));
      return;
    }
    if (segments[0] === "multi") {
      // 🐚️ Not a registered playground variant (no matching Cargo.toml), so this deliberately bypasses
      // `runFrameworkOsPlaygroundDev`/`frameworkOsPlaygroundDevEnv` — those resolve `SEMIO_PLUGIN` from
      // the registry catalog, which a non-variant id would only satisfy by accident. `SEMIO_PLUGIN`
      // stays unset here on purpose (see the `os-dev` `dev multi` branch it forwards to).
      runCmd("bun", ["nx", "run", "@semio-tech/framework-os-dev:dev", "--", "multi", ...segments.slice(1)], {
        cwd: this.root,
        env: { ...process.env, S_OS_PORT: process.env.S_OS_PORT || "6071", SEMIO_RENDERER: process.env.SEMIO_RENDERER ?? "react" },
        ...daemonBudgetOpts(),
      });
      return;
    }
    const playgroundApp = resolvePlaygroundDevApp(segments);
    if (playgroundApp) {
      runFrameworkOsPlaygroundDev(playgroundApp.app, playgroundApp.rest);
      return;
    }
    if (segments[0] === "mcp") {
      this.runMcp(segments.slice(1));
      return;
    }
    if (segments.length > 0) {
      console.error(`[dev] unknown playground app ${JSON.stringify(segments.join(" "))} — regenerate the catalog with bun nx run @semio-tech/plugin-registry:generate if the variant should exist.`);
      process.exit(1);
    }
    runFrameworkOsPlaygroundDev("s");
  }

  private async parseStorybookSegments(segments: string[]): Promise<{ scope: string; args: string[] }> {
    const scopeSegments: string[] = [];
    const args: string[] = [];
    let parsingScope = true;
    for (const segment of segments) {
      if (parsingScope && segment !== "--" && !segment.startsWith("-")) {
        scopeSegments.push(segment);
        continue;
      }
      parsingScope = false;
      if (segment !== "--") args.push(segment);
    }
    // A single scope arg may itself be a comma-list of top-level scopes ("ui,framework/os").
    // Multiple space-separated args keep slash-join behavior for hierarchical scopes ("framework" "os" -> "framework/os").
    const scope = scopeSegments.length === 1 && scopeSegments[0]!.includes(",") ? scopeSegments[0]! : scopeSegments.join("/");
    const scopeIds = scope
      ? scope
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean)
      : [];
    for (const id of scopeIds) {
      if (!/^[a-z0-9][a-z0-9/-]*$/i.test(id)) {
        console.error(`[dev.storybook] invalid scope ${JSON.stringify(id)}`);
        process.exit(1);
      }
    }
    if (scopeIds.length > 0) {
      try {
        const { resolveActiveScopes } = await import("./.storybook/scopes.ts");
        resolveActiveScopes(scopeIds.join(","));
      } catch (error) {
        console.error(error instanceof Error ? `[dev.storybook] ${error.message}` : error);
        process.exit(1);
      }
    }
    return { scope: scopeIds.join(","), args };
  }

  private async runStorybook(extra: string[]): Promise<void> {
    const storybook = await this.parseStorybookSegments(extra);
    const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
    const port = process.env.STORYBOOK_PORT ?? "6010";
    const useExactPort = process.env.STORYBOOK_EXACT_PORT === "1" || process.env.STORYBOOK_EXACT_PORT === "true";
    const storybookArgs = ["storybook", "dev", "-c", ".storybook", "-p", port, ...(useExactPort ? ["--exact-port"] : []), "--host", host, "--no-open", "--debug", ...storybook.args];
    runCmd("bunx", storybookArgs, {
      cwd: this.root,
      env: {
        ...process.env,
        STORYBOOK_SCOPE: storybook.scope,
        WATCHPACK_POLLING: process.env.WATCHPACK_POLLING ?? "true",
        CHOKIDAR_USEPOLLING: process.env.CHOKIDAR_USEPOLLING ?? "true",
      },
      ...daemonBudgetOpts(),
    });
  }

  private async runStorybookStatic(): Promise<void> {
    const host = process.env.STORYBOOK_STATIC_HOST ?? "0.0.0.0";
    const port = Number(process.env.STORYBOOK_PORT ?? "6010");
    const documentRoot = resolve(this.root, "storybook-static");
    const server = Bun.serve({
      hostname: host,
      port,
      async fetch(request) {
        const requestUrl = new URL(request.url);
        const requestPath = decodeURIComponent(requestUrl.pathname);
        const candidatePath = resolve(documentRoot, `.${requestPath}`);
        if (!candidatePath.startsWith(documentRoot)) return new Response("Forbidden", { status: 403 });
        const filePath = await (async () => {
          try {
            const fileInfo = await stat(candidatePath);
            if (fileInfo.isDirectory()) return resolve(candidatePath, "🌐️.html");
            return candidatePath;
          } catch {
            if (extname(candidatePath) === "") return resolve(candidatePath, "🌐️.html");
            return candidatePath;
          }
        })();
        try {
          const file = Bun.file(filePath);
          if (!(await file.exists())) return new Response("Not Found", { status: 404 });
          return new Response(file);
        } catch {
          return new Response("Not Found", { status: 404 });
        }
      },
    });

    console.log(`storybook-static listening on http://${host}:${port}`);
    await new Promise(() => {});
  }

  private runMcp(segments: string[]): void {
    const a = segments[0];
    if (a === "neo4j") {
      this.runMcpNeo4j(segments.slice(1));
      return;
    }
    if (a === "stdio") {
      const rest = segments.slice(1);
      if ((rest[0] ?? "").trim().toLowerCase() === "os") {
        this.runMcpOs("stdio", rest.slice(1));
        return;
      }
      this.runMcpStdioRepo(rest);
      return;
    }
    if (a === "http") {
      const rest = segments.slice(1);
      if ((rest[0] ?? "").trim().toLowerCase() === "os") {
        this.runMcpOs("http", rest.slice(1));
        return;
      }
      console.error("[dev] `dev mcp http` currently serves only the os gateway — use `dev mcp http os`.");
      process.exit(1);
    }
    const mode = a === "repo" ? "repo" : "default";
    const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
    if (mode === "repo") {
      runCmd("npx", ["--yes", "@modelcontextprotocol/inspector", "--config", ".cursor/mcp.json", "--server", "repo"], {
        cwd: this.root,
        env: { ...process.env, HOST: host },
        ...daemonBudgetOpts(),
      });
      return;
    }
    runCmd("npx", ["--yes", "@modelcontextprotocol/inspector"], { cwd: this.root, ...daemonBudgetOpts() });
  }

  private runMcpNeo4j(neoSegments: string[]): void {
    const { nameParts, passthrough } = partitionNeo4jGraphCliArgv(neoSegments);
    const hasName = nameParts.length > 0;
    const graphDatabase = hasName ? joinNeo4jGraphDatabaseName(nameParts) : process.env.NEO4J_DATABASE || defaultNeo4jGraphDatabaseName();
    const args = [...passthrough];
    if (hasName && !args.includes("--namespace")) args.push("--namespace", graphDatabase);
    runCmd("uvx", ["mcp-neo4j-cypher", ...args], {
      cwd: this.root,
      env: {
        ...process.env,
        NEO4J_URI: process.env.NEO4J_URI || "bolt://localhost:7687",
        NEO4J_USERNAME: process.env.NEO4J_USERNAME || "neo4j",
        NEO4J_PASSWORD: process.env.NEO4J_PASSWORD || "password",
        NEO4J_DATABASE: graphDatabase,
        NEO4J_TELEMETRY: process.env.NEO4J_TELEMETRY || "false",
      },
      ...daemonBudgetOpts(),
    });
  }

  /** 🌉️ Runs the `semio-os` MCP gateway (`semio-framework-os-mcp`) over stdio or Streamable HTTP.
   * `stdio` is what `.mcp.json` launches; `http` defaults to port 6300 (outside the 6012–6205
   * catalog range and the 7300+ bench pool). Extra argv passes straight through to the binary
   * (`--folder`, `--hub`, `--principal`, `--scopes`, `--auto-approve`, …). */
  private runMcpOs(transport: "stdio" | "http", extra: string[]): void {
    const args = ["run", "--quiet", "-p", "semio-framework-os-mcp", "--bin", "semio-os-mcp", "--", transport, ...extra];
    if (transport === "http" && !extra.includes("--port")) {
      args.push("--port", process.env.S_OS_MCP_PORT ?? "6300");
    }
    runCmd("cargo", args, { cwd: this.root, ...daemonBudgetOpts() });
  }

  private runMcpStdioRepo(slugs: string[]): void {
    const slug = (slugs[0] ?? "client").trim().toLowerCase();
    const extra = slugs.slice(1);
    const bin = buildRepoMcpClient(this.root);
    runCmd(bin, ["mcp", slug, ...extra], {
      cwd: this.root,
      env: { ...process.env, GOWORK: join(this.root, "go.work") },
      ...daemonBudgetOpts(),
    });
  }
}
//#endregion 🔖️DevScript

//#region 🔖️NxScript
export class NxScript extends Script {
  run(segments: string[]): void {
    runCmd("node", [join(this.root, "node_modules", "nx", "bin", "nx.js"), ...segments], {
      cwd: this.root,
      env: devToolingEnv(),
      ...orchestratorBudgetOpts(),
    });
  }
}
//#endregion 🔖️NxScript

//#region 🔖️GenerateScript
function taxonomyOption(args: readonly string[], name: string): string | undefined {
  const index = args.indexOf(name);
  return index >= 0 ? args[index + 1] : undefined;
}

function taxonomyContractFilename(taxonomy: ReturnType<typeof loadTaxonomy>, contractId: string): string {
  const fixed = taxonomy.fixedFilenameContracts[contractId];
  const filename = fixed ? fixedContractFilename(fixed) : taxonomy.configurableEntryContracts[contractId]?.filename;
  if (!filename) throw new Error(`[taxonomy] unknown filename contract ${JSON.stringify(contractId)}.`);
  return filename;
}

function taxonomyContractFilenames(taxonomy: ReturnType<typeof loadTaxonomy>, contractIds: readonly string[]): string[] {
  return contractIds.map((contractId) => taxonomyContractFilename(taxonomy, contractId));
}

function taxonomyMappedFilename(taxonomy: ReturnType<typeof loadTaxonomy>, mapping: Readonly<Record<string, string>>, key: string): string {
  const fileKindId = mapping[key];
  if (!fileKindId) throw new Error(`[taxonomy] no file-kind mapping for ${JSON.stringify(key)}.`);
  return canonicalPrimaryFilenameForKind(fileKindId, taxonomy);
}

function taxonomyEcosystemEntryFilenames(taxonomy: ReturnType<typeof loadTaxonomy>, ecosystemId: string): string[] {
  return taxonomyContractFilenames(taxonomy, taxonomy.ecosystems[ecosystemId]?.entryContractIds ?? []);
}

/** 🎫️ Resolves a ticket id through actual Unicode directory entries instead of constructing emoji mounts. */
function taxonomyTicketDirectory(repoRoot: string, ticketId: string): string {
  const parts = ticketId.split("/").filter(Boolean);
  if (parts.length !== 4) throw new Error(`[taxonomy] ticket id must be YYYY/MM/DD/TICKETSLUG, got ${JSON.stringify(ticketId)}.`);
  let current = realpathSync(join(getRepoMetaDir(repoRoot), "🎫️tickets"));
  for (const part of parts) {
    const entry = readdirSync(current, { withFileTypes: true })
      .filter((candidate) => candidate.isDirectory())
      .sort((a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
      .find((candidate) => candidate.name === part || candidate.name.replace(/^\p{Extended_Pictographic}\uFE0F?/u, "") === part);
    if (!entry) throw new Error(`[taxonomy] ticket segment ${JSON.stringify(part)} does not exist below ${current}.`);
    current = realpathSync(join(current, entry.name));
  }
  return current;
}

//#region 🧩️Nested Cargo Adapter Generation
/** 🧩️ Emits or verifies exactly the JCO Cargo library adapter from schema-owned bytes. */
export function runNestedCargoPackageAdapter(repoRoot: string, mode: string): void {
  if (!["preview", "generate", "check"].includes(mode)) throw new Error("Package adapter mode must be preview, generate, or check");
  const adapters = semanticPackageAdapterPreview(repoRoot, "jcoprobe-guest");
  const nodes = adapters.map((entry) => ({ bytesBase64: Buffer.from(entry.content).toString("base64"), mode: 0o644, nodeKind: "file" as const, path: entry.path }));
  if (mode === "preview") { process.stdout.write(canonicalJson({ contractId: "jco-package-adapter", nodes, schemaVersion: 1, staleRemovals: [] }) + "\n"); return; }
  for (const adapter of adapters) {
    const path = join(repoRoot, adapter.path);
    if (!existsSync(join(dirname(dirname(path)), "Cargo.toml"))) throw new Error("Package adapter generation requires its canonical Cargo manifest");
    if (existsSync(path)) {
      if (readFileSync(path, "utf8") !== adapter.content || (lstatSync(path).mode & 0o7777) !== 0o644) throw new Error("Package adapter bytes or mode drift: " + adapter.path);
      continue;
    }
    if (mode === "check") throw new Error("Package adapter is absent: " + adapter.path);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, adapter.content, { flag: "wx", mode: 0o644 });
  }
}
/** 🌐️ Builds browser artifacts entirely in memory from exact no-follow source or projected inputs. */
export async function renderWgpuBrowserBundles(repoRoot: string, input: unknown, owner: SemanticPackageProjectionCase, layout: "source" | "destination", options: { readonly taxonomy?: ReturnType<typeof loadTaxonomy>; readonly view?: RegistryCatalogInputView; readonly isCancelled?: () => boolean; readonly progress?: (event: { readonly phase: "module-input" | "bundle"; readonly completed: number; readonly total: number }) => void } = {}): Promise<{ readonly nodes: readonly { readonly path: string; readonly content: string; readonly mode: number; readonly inclusion: "tracked" | "ignored" }[]; readonly inputs: readonly string[] }> {
  const profile = parseSemanticPackageBrowserProfile(input, owner), taxonomy = options.taxonomy ?? loadTaxonomy();
  if (layout !== "source" && layout !== "destination") throw new Error("WGPU browser layout must be source or destination");
  const view = options.view ?? registryCatalogInputView(repoRoot, taxonomy);
  const projected = (path: string): string => layout === "destination" ? owner.mappings.find((mapping) => mapping.sourcePath === path)?.destinationPath ?? path : path;
  const allowed = new Set(profile.sourceModulePaths.map(projected)), modules = new Set<string>(), contents = new Map<string, string>();
  const nodes: { path: string; content: string; mode: number; inclusion: "tracked" | "ignored" }[] = [];
  const check = (): void => { if (options.isCancelled?.()) throw new Error("WGPU browser generation cancelled"); };
  const read = (path: string): string => {
    check();
    const cached = contents.get(path);
    if (cached !== undefined) return cached;
    if (view.kind(path) !== "file") throw new Error("WGPU browser input is missing or not a no-follow file: " + path);
    const content = view.readText(path), mapping = owner.mappings.find((mapping) => mapping.sourcePath === path);
    if (layout === "source" && mapping && (createHash("sha256").update(content).digest("hex") !== mapping.sourceHash || Buffer.byteLength(content) !== mapping.sourceSize)) throw new Error("WGPU browser source preimage drift: " + path);
    contents.set(path, content);
    return content;
  };
  check();
  for (const [name, binding] of Object.entries(profile.workspaceImports)) {
    const manifest = JSON.parse(read(binding.manifestPath));
    if (manifest.name !== name || manifest.exports?.["."] !== "./" + relative(dirname(binding.manifestPath), binding.entryPath).replaceAll("\\", "/")) throw new Error("WGPU browser workspace manifest drift: " + name);
  }
  for (const entry of profile.entries) {
    check();
    const mapping = owner.mappings.find((mapping) => mapping.sourcePath === owner.sourceRoot + "/" + entry.sourceRelativePath)!;
    const entryPath = projected(mapping.sourcePath), entryAbsolute = join(repoRoot, entryPath);
    const result = await Bun.build({ root: repoRoot, entrypoints: [entryAbsolute], target: "browser", format: "esm", define: { "import.meta.vitest": profile.inlineTestDefine }, plugins: [{ name: "semantic-wgpu-owned-inputs", setup(builder) {
      builder.onResolve({ filter: /.*/u }, (request) => {
        check();
        const path = request.path === entryAbsolute ? entryPath : request.path.startsWith(".") ? relative(repoRoot, resolve(repoRoot, dirname(request.importer), request.path)).replaceAll("\\", "/") : profile.workspaceImports[request.path]?.entryPath;
        if (!path || !allowed.has(path)) throw new Error("WGPU browser import is not schema-owned: " + request.path + " in " + request.importer);
        return { path, namespace: "owned-wgpu" };
      });
      builder.onLoad({ filter: /.*/u, namespace: "owned-wgpu" }, (request) => {
        if (!allowed.has(request.path)) throw new Error("WGPU browser module is not schema-owned: " + request.path);
        const content = read(request.path);
        modules.add(request.path);
        options.progress?.({ phase: "module-input", completed: modules.size, total: allowed.size });
        check();
        return { contents: content, loader: request.path.endsWith(".tsx") ? "tsx" : request.path.endsWith(".json") ? "json" : "ts" };
      });
    } }] });
    check();
    if (!result.success || result.logs.length || result.outputs.length !== 1) throw new Error("WGPU browser compilation did not produce exactly one clean artifact: " + entry.id);
    nodes.push({ path: dirname(mapping.destinationPath).replaceAll("\\", "/") + "/🤖️generated/🟨️.js", content: await result.outputs[0]!.text(), mode: 0o644, inclusion: entry.inclusion });
    options.progress?.({ phase: "bundle", completed: nodes.length, total: profile.entries.length });
  }
  check();
  const unused = [...allowed].filter((path) => !modules.has(path));
  if (unused.length) throw new Error("WGPU browser module authority includes unread inputs: " + unused.join(" | "));
  const compare = (left: string, right: string): number => Buffer.compare(Buffer.from(left), Buffer.from(right));
  return { nodes: nodes.sort((left, right) => compare(left.path, right.path)), inputs: [...contents.keys()].sort(compare) };
}

/** 🥖️ Requires one exact root package-manager identity for all WGPU artifact commands. */
export function assertWgpuPackageToolchain(packageManager: unknown, actualVersion: string = Bun.version): string {
  const expected = typeof packageManager === "string" ? /^bun@(\d+\.\d+\.\d+)$/u.exec(packageManager)?.[1] : undefined;
  if (!expected || actualVersion !== expected) throw new Error("WGPU generation requires the exact root Bun packageManager identity");
  return expected;
}

function loadWgpuPackageTaxonomy(repoRoot: string): ReturnType<typeof loadTaxonomy> {
  const taxonomy = JSON.parse(readFileSync(resolveWorkspaceTaxonomyAuthority(repoRoot).taxonomyPath, "utf8"));
  const problems = validateTaxonomy(taxonomy);
  if (problems.length) throw new Error("WGPU package schema is invalid: " + problems.join(" | "));
  return taxonomy;
}

/** 🏗️ Renders six exact artifacts only after proving every canonical authored package leaf. */
export async function renderWgpuPackageArtifacts(repoRoot: string, options: { readonly taxonomy?: ReturnType<typeof loadTaxonomy>; readonly view?: RegistryCatalogInputView; readonly isCancelled?: () => boolean; readonly progress?: (event: { readonly phase: "module-input" | "bundle"; readonly completed: number; readonly total: number }) => void } = {}) {
  const taxonomy = options.taxonomy ?? loadWgpuPackageTaxonomy(repoRoot), contract = taxonomy.generatorContracts["wgpu-frame-worker"];
  const catalog = semanticPackageProjectionCatalog(repoRoot, taxonomy), owner = catalog?.packages.find((entry) => entry.id === "wgpu-renderer");
  if (!catalog || !owner || !contract?.packageGeneration) throw new Error("WGPU package generation lacks exact catalog authority");
  const view = options.view ?? registryCatalogInputView(repoRoot, taxonomy), inputs = new Set<string>();
  const check = (): void => { if (options.isCancelled?.()) throw new Error("WGPU package generation cancelled"); };
  const read = (path: string): string => { check(); if (view.kind(path) !== "file") throw new Error("WGPU canonical input is missing or not a no-follow file: " + path); inputs.add(path); return view.readText(path); };
  check();
  if (owner.mappings.some((mapping) => view.kind(mapping.sourcePath) !== null)) throw new Error("WGPU generation requires canonical package inputs without old source leaves");
  const rootManifest = read("package.json");
  assertWgpuPackageToolchain(JSON.parse(rootManifest).packageManager);
  const browser = await renderWgpuBrowserBundles(repoRoot, contract.packageGeneration.browserProfile, owner, "destination", { ...options, taxonomy, view });
  const generated = [...owner.adapters.filter((adapter) => !owner.mappings.some((mapping) => mapping.destinationPath === adapter.path)), ...owner.derivedLeaves];
  const nodes = [...generated.map(({ path, content }) => ({ path, content, mode: 0o644, inclusion: "tracked" as const })), ...browser.nodes].sort((left, right) => Buffer.compare(Buffer.from(left.path), Buffer.from(right.path)));
  if (canonicalJson(nodes.map(({ path, inclusion }) => ({ path, inclusion }))) !== canonicalJson(contract.outputRoots)) throw new Error("WGPU generated roots disagree with the exact package catalog");
  for (const node of nodes) { const kind = view.kind(node.path); if (kind !== null && kind !== "file") throw new Error("WGPU generated output is not a no-follow file: " + node.path); }
  const facts: SemanticProjectionAuthorityNode[] = owner.mappings.map((mapping) => ({ path: mapping.destinationPath, nodeKind: "file", content: mapping.disposition === "generated" ? nodes.find((node) => node.path === mapping.destinationPath)!.content : read(mapping.destinationPath) }));
  for (const leaf of generated) facts.push({ path: leaf.path, nodeKind: "file", content: view.kind(leaf.path) === "file" ? view.readText(leaf.path) : leaf.content });
  const authority = semanticPackageProjectionAuthority({ packageId: owner.id, nodes: facts, layout: "destination", cargoWorkspaceContent: read("Cargo.toml"), nodeWorkspaceContent: rootManifest }, catalog, taxonomy);
  if (authority.problems.length) throw new Error("WGPU canonical package identity: " + authority.problems.join(" | "));
  check();
  return { nodes, inputs: [...new Set([...inputs, ...browser.inputs])].sort((left, right) => Buffer.compare(Buffer.from(left), Buffer.from(right))) };
}

/** ⚙️ Executes exact preview, generation, or freshness commands without writing outside six owned leaves. */
export async function runWgpuPackageGenerator(repoRoot: string, mode: string, options: { readonly taxonomy?: ReturnType<typeof loadTaxonomy>; readonly isCancelled?: () => boolean } = {}): Promise<void> {
  if (!["preview", "generate", "check"].includes(mode)) throw new Error("WGPU package mode must be preview, generate, or check");
  const taxonomy = options.taxonomy ?? loadWgpuPackageTaxonomy(repoRoot);
  const problems = validateTaxonomy(taxonomy);
  if (problems.length) throw new Error("WGPU package schema is invalid: " + problems.join(" | "));
  const contract = taxonomy.generatorContracts["wgpu-frame-worker"], protocol = contract?.packageGeneration?.previewInput;
  if (!protocol) throw new Error("WGPU package preview authority is absent");
  const cancelFile = process.env.SEMIO_GENERATOR_PREVIEW_CANCEL_FILE, base = registryCatalogInputView(repoRoot, taxonomy);
  const cancelPath = cancelFile ? relative(repoRoot, resolve(cancelFile)).replaceAll("\\", "/") : undefined;
  if (cancelFile && (!cancelPath || cancelPath.startsWith("../") || cancelPath === ".." || isAbsolute(cancelPath))) throw new Error("WGPU cancellation path is outside the repository");
  const isCancelled = (): boolean => Boolean(options.isCancelled?.() || cancelPath && registryCatalogInputView(repoRoot, taxonomy).kind(cancelPath) !== null);
  let view = base;
  const selected = process.env.SEMIO_GENERATOR_PREVIEW_PROTOCOL;
  if (selected) {
    if (mode !== "preview" || selected !== protocol.protocol) throw new Error("WGPU projected inputs require the exact preview protocol");
    const chunks: Uint8Array[] = [];
    let size = 0;
    for await (const chunk of Bun.stdin.stream()) {
      if (isCancelled()) throw new Error("WGPU package preview cancelled");
      size += chunk.byteLength;
      if (size > protocol.maxBytes) throw new Error("WGPU projected inputs exceed the declared byte bound");
      chunks.push(chunk);
    }
    view = generatorProjectedInputView(repoRoot, taxonomy, parseGeneratorInputProjection(Buffer.concat(chunks).toString("utf8"), taxonomy, "wgpu-frame-worker"), base);
  }
  const rendered = await renderWgpuPackageArtifacts(repoRoot, { taxonomy, view, isCancelled });
  if (mode === "preview") {
    const nodes = rendered.nodes.map(({ path, content, mode }) => ({ path, nodeKind: "file", mode, bytesBase64: Buffer.from(content).toString("base64") }));
    process.stdout.write(canonicalJson({ contractId: "wgpu-frame-worker", schemaVersion: 1, nodes, staleRemovals: [] }) + "\n");
    return;
  }
  const changed = rendered.nodes.filter((node) => {
    const kind = registryCatalogInputView(repoRoot, taxonomy).kind(node.path);
    if (kind === null) return true;
    const path = join(repoRoot, node.path);
    if (kind !== "file" || (lstatSync(path).mode & 0o7777) !== node.mode) throw new Error("WGPU output mode or no-follow kind drift: " + node.path);
    return readFileSync(path, "utf8") !== node.content;
  });
  if (mode === "check" && changed.length) throw new Error("WGPU package output is absent or stale: " + changed[0]!.path);
  for (const node of changed) {
    if (isCancelled()) throw new Error("WGPU package generation cancelled");
    const path = join(repoRoot, node.path);
    registryCatalogInputView(repoRoot, taxonomy).kind(node.path);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, node.content, { mode: node.mode });
  }
  process.stderr.write(`[wgpu] ${mode}: ${rendered.nodes.length} exact artifacts; ${changed.length} changed\n`);
}
//#endregion 🧩️Nested Cargo Adapter Generation

export class GenerateScript extends Script {
  run(segments: string[]): void {
    if (segments[0] === "taxonomy") {
      this.generateTaxonomy(segments.slice(1));
      return;
    }
    if (segments[0] === "neo4j") {
      new Neo4jCypherExport(this.root).runFromArgv(segments.slice(1));
      return;
    }
    if (segments[0] === "plugin-glue") {
      this.generatePluginGlue(segments.slice(1));
      return;
    }
    if (segments[0] === "scale-fixture") {
      runCmd("bun", ["nx", "run", "@semio-tech/framework-os-dev:generate-scale-fixture", ...segments.slice(1)], { cwd: this.root });
      return;
    }
    let successes = 0;
    let failures = 0;
    const exporter = new Neo4jCypherExport(this.root);
    for (const spec of getAllNeo4jGraphExportSpecs(process.env)) {
      const joined = joinNeo4jGraphDatabaseName(spec);
      const prev = process.env.NEO4J_DATABASE;
      process.env.NEO4J_DATABASE = joined;
      try {
        if (exporter.tryExportFromArgv([...spec])) successes += 1;
        else {
          failures += 1;
          console.error(`[generate] neo4j (${joined}) failed.`);
        }
      } finally {
        if (prev === undefined) delete process.env.NEO4J_DATABASE;
        else process.env.NEO4J_DATABASE = prev;
      }
    }
    if (successes === 0) {
      console.error("[generate] no Neo4j database could be exported.");
      process.exit(1);
    }
    if (failures > 0) {
      console.error(`[generate] partial success (${successes} ok, ${failures} failed).`);
    }
    console.log(`[generate] Neo4j Cypher export finished (${successes} ok, ${failures} skipped/failed) under .🧬semio/🦑️repo/🛂️manifest.`);
  }

  /** 🧩️ Writes deterministic census or duplicate evidence with its Markdown companion. */
  private generateTaxonomy(args: string[]): void {
    const operation = args[0];
    if (operation === "package-adapter") {
      runNestedCargoPackageAdapter(this.root, args[1] ?? "preview");
      return;
    }
    if (operation !== "census" && operation !== "duplicates") throw new Error(`[generate taxonomy] expected census or duplicates, got ${JSON.stringify(operation)}.`);
    const ticketId = taxonomyOption(args, "--ticket");
    if (!ticketId) throw new Error(`[generate taxonomy ${operation}] --ticket <ticket-id> is required.`);
    const ticketDir = taxonomyTicketDirectory(this.root, ticketId);
    const census = buildSemanticCensus(this.root);
    if (operation === "census") {
      writeFileSync(join(ticketDir, "📊️semantic-census.json"), renderSemanticCensusJson(census));
      writeFileSync(join(ticketDir, "📓️semantic-census.md"), renderSemanticCensusMarkdown(census));
    } else {
      writeFileSync(join(ticketDir, "📊️semantic-duplicates.json"), renderSemanticDuplicatesJson(census));
      writeFileSync(join(ticketDir, "📓️semantic-duplicates.md"), renderSemanticDuplicatesMarkdown(census));
    }
    console.log(`[generate taxonomy ${operation}] ${census.records.length} components, ${census.problems.length} findings -> ${ticketDir}`);
  }

  /** 🧬️ Emit deterministic #[path] wiring comments for subset/example modules (dry by default). */
  private generatePluginGlue(args: string[]): void {
    const dry = args.includes("--dry") || args.includes("--dry-run") || args.length === 0;
    const pluginFilter = args.find((a) => !a.startsWith("--"));
    const pluginsRoot = join(this.root, "✏️s/🔌️plugins");
    const plugins = readdirSync(pluginsRoot, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name);
    let emitted = 0;
    for (const plugin of plugins) {
      if (pluginFilter && plugin !== pluginFilter && !plugin.includes(pluginFilter)) continue;
      const owned = policyListTopLevelSubsetDirs(this.root).filter((s) => s.split("/")[2] === plugin);
      const lines: string[] = [
        `// GENERATED-BY: bun ./📜️script.ts generate plugin-glue ${plugin}`,
        `// subsets=${owned.length} (registration body still hand-authored until serializer wave; this command validates discoverability)`,
      ];
      for (const sub of owned) {
        lines.push(`// subset: ${sub}`);
        emitted += 1;
      }
      const glue = join(pluginsRoot, plugin, "📦️packages/🦀️rust/🦀️.rs");
      if (!existsSync(glue)) {
        console.warn(`[generate plugin-glue] skip ${plugin}: missing glue.rs`);
        continue;
      }
      if (dry) {
        console.log(`[generate plugin-glue] dry ${plugin}: ${owned.length} subsets`);
      } else {
        const inv = join(pluginsRoot, plugin, "📦️packages/🦀️rust/🤖️generated-subset-inventory.txt");
        writeFileSync(inv, lines.join("\n") + "\n");
        console.log(`[generate plugin-glue] wrote ${inv}`);
      }
    }
    console.log(`[generate plugin-glue] ${dry ? "dry-run" : "wrote"} inventory for ${emitted} subset refs`);
  }
}
//#endregion 🔖️GenerateScript

//#region 🔖️LintScript
export class LintScript extends Script {
  run(segments: string[]): void {
    // nx orchestrators: exempt — total wall time spans every project and legitimately exceeds any single
    // command's budget; each leaf project's own build/test/lint commands are individually budgeted.
    if (segments[0] === "repo") {
      runCmd("bun", ["nx", "run-many", "-t", "lint", "-p", "@repo/*"], { cwd: this.root, ...orchestratorBudgetOpts() });
      return;
    }
    runCmd("bun", ["nx", "run-many", "-t", "lint", "--all", "--exclude", "workspace"], { cwd: this.root, ...orchestratorBudgetOpts() });
    runCmd("bunx", ["dependency-cruiser", "🧰️framework", "✏️s", "🌎️hub", "♻️mit-bestand", "--config", ".dependency-cruiser.cjs", "--output-type", "err"], { cwd: this.root, shell: true });
  }
}
//#endregion 🔖️LintScript

//#region 🔖️VerifyScript
/** 🦀️ Every plugin crate name under `✏️s/🔌️plugins`, read from each crate's own `Cargo.toml`. */
function pluginCrateNames(root: string): string[] {
  const names: string[] = [];
  const pluginsRoot = join(root, "✏️s", "🔌️plugins");
  if (!existsSync(pluginsRoot)) return names;
  for (const owner of readdirSync(pluginsRoot)) {
    const manifest = join(pluginsRoot, owner, "📦️packages", "🦀️rust", "Cargo.toml");
    if (!existsSync(manifest)) continue;
    const name = readFileSync(manifest, "utf8").match(/\[package\][\s\S]*?\bname\s*=\s*"([^"]+)"/)?.[1];
    if (name) names.push(name);
  }
  return names.sort();
}

/**
 * 🎯️ Which crates each compilation target exists to prove warning-free, and how to scope the build.
 * `--all-targets` (tests, benches, examples) is right for native but wrong for the wasm triples:
 * plugin test harnesses are native-only, so a wasm `--all-targets` clippy fails on code that target
 * never ships. `wasm32-wasip2` therefore builds the plugins' real component library surface, and
 * `wasm32-unknown-unknown` the pure actor kernel — the crate whose purity keeps mobile open.
 */
function rustWarningTargetScope(root: string, target: string | undefined): { packages: string[]; scopeArgs: string[]; targetArgs: string[] } {
  // 🐛️ No `--features component-guest` here: plugin crates declare NO `[features]` section of their
  // own — `component-guest` is a DEPENDENCY feature they each enable unconditionally on
  // `semio-framework-plugin` (`features = ["component-guest"]` on that dep line). Passing it to
  // `cargo -p <plugin>` fails with "does not contain this feature", which blocked this target 100%
  // of the time. Reported independently by D0 and Z1 before it was believed.
  if (target === "wasm32-wasip2") return { packages: pluginCrateNames(root), scopeArgs: ["--lib"], targetArgs: ["--target", target] };
  if (target === "wasm32-unknown-unknown") return { packages: ["semio-framework-actor"], scopeArgs: ["--lib"], targetArgs: ["--target", target] };
  if (target && target !== "native") throw new Error(`[verify rust-warnings] unknown target ${target} (expected native | wasm32-wasip2 | wasm32-unknown-unknown).`);
  return { packages: ["semio-framework-actor", "semio-framework", "semio-framework-os-kernel", ...pluginCrateNames(root)], scopeArgs: ["--all-targets"], targetArgs: [] };
}

//#region 🎯️ToolJobCoverage
type ToolJobCoverageReport = {
  macroHostFiles: number;
  macroInvocations: number;
  commandRows: number;
  uniqueCommandRows: number;
  duplicateRows: { file: string; id: string }[];
  fixtureMacroHostFiles: number;
  fixtureMacroInvocations: number;
  fixtureCommandRows: number;
  boundedRows: number;
  batchOnlyRows: number;
  forbiddenRows: number;
  deletedRows: number;
  productionFactories: number;
  productionRegistrations: number;
  productionDispatches: number;
  aliases: number;
  factoryContracts: { file: string; line: number; factory: string; status: "explicit" | "missing" }[];
  frameworkReservedRoutes: { id: string; status: "failClosedPendingFactory" }[];
  reservedImporterOwners: { owner: string; file: string; id: "import-media"; status: "failClosedPendingFactory" }[];
  globalPayloadStores: GlobalPayloadStoreInventoryRow[];
  globalPayloadStoreExemptions: GlobalPayloadStoreInventoryRow[];
  scanThenMonolithRows: { file: string; id: string; helper: string }[];
  literalRegistrations: number;
  acceptedCommandRows: ToolJobStaticRow[];
  acceptedReservedRoutes: string[];
  remainingCommands: { file: string; id: string; reason: string; source: "literal" | "macro" }[];
  pipelineGates: {
    fullToolOperationJobBounded: boolean;
    durableOneItemPublicationBounded: boolean;
    ephemeralOneItemPublicationBounded: boolean;
    fullToolOperationBounded: boolean;
  };
  selfTests: number;
  failures: string[];
};

/** 🎯️ Finds the matching Rust brace while ignoring quoted strings and comments. */
function toolJobRustBlock(source: string, open: number): { body: string; end: number } | undefined {
  let depth = 0;
  let string = false;
  let lineComment = false;
  let blockComment = 0;
  let escaped = false;
  for (let index = open; index < source.length; index += 1) {
    const char = source[index]!;
    const next = source[index + 1] ?? "";
    if (lineComment) {
      if (char === "\n") lineComment = false;
      continue;
    }
    if (blockComment > 0) {
      if (char === "/" && next === "*") {
        blockComment += 1;
        index += 1;
      } else if (char === "*" && next === "/") {
        blockComment -= 1;
        index += 1;
      }
      continue;
    }
    if (string) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') {
        string = false;
      }
      continue;
    }
    if (char === "/" && next === "/") {
      lineComment = true;
      index += 1;
      continue;
    }
    if (char === "/" && next === "*") {
      blockComment = 1;
      index += 1;
      continue;
    }
    if (char === '"') string = true;
    else if (char === "{") depth += 1;
    else if (char === "}" && --depth === 0) return { body: source.slice(open + 1, index), end: index + 1 };
  }
  return undefined;
}

function toolJobRustArray(source: string, open: number): { body: string; end: number } | undefined {
  if (source[open] !== "[") return undefined;
  let depth = 0;
  let string = false;
  let escaped = false;
  let lineComment = false;
  let blockComment = 0;
  for (let index = open; index < source.length; index += 1) {
    const char = source[index]!;
    const next = source[index + 1];
    if (lineComment) {
      if (char === "\n") lineComment = false;
      continue;
    }
    if (blockComment > 0) {
      if (char === "/" && next === "*") {
        blockComment += 1;
        index += 1;
      } else if (char === "*" && next === "/") {
        blockComment -= 1;
        index += 1;
      }
      continue;
    }
    if (string) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') string = false;
      continue;
    }
    if (char === "/" && next === "/") {
      lineComment = true;
      index += 1;
      continue;
    }
    if (char === "/" && next === "*") {
      blockComment = 1;
      index += 1;
      continue;
    }
    if (char === '"') string = true;
    else if (char === "[") depth += 1;
    else if (char === "]" && --depth === 0) return { body: source.slice(open + 1, index), end: index + 1 };
  }
  return undefined;
}

type ToolJobStaticRow = { file: string; id: string; source: "literal" | "macro" };

type ToolJobPublicationLane = "HostOnly" | "Artifact" | "Config" | "Draft" | "Presence" | "Transient" | "Child";
type ToolJobAppOwnedRow = {
  ownerFile: string;
  factoryFile: string;
  ownerTypeName: string;
  factory: string;
  toolId: string;
  publicationLanes: readonly ToolJobPublicationLane[];
  publicationReady: boolean;
};

type GlobalPayloadStoreKind = "child-content-scratch" | "resizable-operation-registry" | "fixed-operation-registry" | "abi-bridge-retention" | "mutable-entropy" | "mutable-payload";
type GlobalPayloadStoreOwner = { name: string; rustType: string; kind: GlobalPayloadStoreKind };
type GlobalPayloadStoreInventoryRow = { file: string; line: number; text: string; owners: GlobalPayloadStoreOwner[] };

const TOOL_JOB_FRAMEWORK_RESERVED_IDS = [
  "undo",
  "redo",
  "commitCheckpoint",
  "createAlternative",
  "switchAlternative",
  "checkoutCheckpoint",
  "revertToCommand",
  "copy",
  "cut",
  "paste",
  "noteShellCommand",
  "setHistoryCommandFilter",
  "recordTutorial",
  "clearSelection",
  "interactionHover",
  "interactionSelect",
  "selectAll",
  "setInteractionGranularity",
  "setSelectionMode",
  "configuration-binary",
] as const;
const TOOL_JOB_PLUGIN_RESERVED_IDS = ["copy", "cut", "paste", "import-media"] as const;
const TOOL_JOB_RESERVED_IDS = [...TOOL_JOB_FRAMEWORK_RESERVED_IDS, ...TOOL_JOB_PLUGIN_RESERVED_IDS] as const;
const TOOL_JOB_IMPORTER_INVENTORY = ".🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️20/INTERACTIVE-JOB-RUNTIME-REFACTOR/EVERY-TOOL-INTERACTIVE-JOB-MIGRATION/📊️p8yj-importer-cohorts.json";
const TOOL_JOB_CHILD_RETIREMENT_INVENTORY = ".🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️20/INTERACTIVE-JOB-RUNTIME-REFACTOR/EVERY-TOOL-INTERACTIVE-JOB-MIGRATION/📊️p8yt-child-snapshot-retirement-cohorts.json";

/** 🧹️ Removes in-file test modules from the production registration census. */
function toolJobProductionSource(source: string): string {
  const lines = source.split("\n");
  for (const span of policyTestModSpans(lines)) for (let line = span.startLine - 1; line < span.endLine; line += 1) lines[line] = "";
  return lines.join("\n");
}

function toolJobProductionProtocolSource(raw: string): string {
  let source = toolJobProductionSource(raw);
  const marker = /#\[cfg\((?:all\([^\]]*\btest\b[^\]]*\)|test)\)\]/g;
  for (;;) {
    const match = marker.exec(source);
    if (!match) return source;
    const item = match.index + match[0].length;
    let parentheses = 0;
    let brackets = 0;
    let end = source.length;
    for (let index = item; index < source.length; index += 1) {
      const char = source[index]!;
      if (char === "(") parentheses += 1;
      else if (char === ")") parentheses -= 1;
      else if (char === "[") brackets += 1;
      else if (char === "]") brackets -= 1;
      else if (char === ";" && parentheses === 0 && brackets === 0) {
        end = index + 1;
        break;
      } else if (char === "{" && parentheses === 0 && brackets === 0) {
        end = toolJobRustBlock(source, index)?.end ?? source.length;
        break;
      }
    }
    source = `${source.slice(0, match.index)}${" ".repeat(end - match.index)}${source.slice(end)}`;
    marker.lastIndex = 0;
  }
}

function toolJobGlobalPayloadStoreInventory(files: ReadonlyMap<string, string>): GlobalPayloadStoreInventoryRow[] {
  const kindOf = (name: string, rustType: string): GlobalPayloadStoreKind => {
    if (/BRIDGE|RETAINED/.test(name)) return "abi-bridge-retention";
    if (/SCRATCH|STAGING|BLOBS|BATCHES/.test(name)) return "child-content-scratch";
    if (/ENTROPY|SEED/.test(name) && /Cells*</.test(rustType)) return "mutable-entropy";
    if (/HashMap|BTreeMap|Vecs*</.test(rustType)) return "resizable-operation-registry";
    if (/\[[^\]]*;[^\]]+\]|Registry|Recovery|ArenaProcessState/.test(rustType)) return "fixed-operation-registry";
    return "mutable-payload";
  };
  const ownersOf = (source: string): GlobalPayloadStoreOwner[] => {
    const owners: GlobalPayloadStoreOwner[] = [];
    for (const owner of source.matchAll(/\bstatic\s+([A-Z][A-Z0-9_]*)\s*:\s*([^=]+?)\s*=/g)) {
      const rustType = owner[2]!.trim().replaceAll(/\s+/g, " ");
      owners.push({ name: owner[1]!, rustType, kind: kindOf(owner[1]!, rustType) });
    }
    return owners;
  };
  const rows: GlobalPayloadStoreInventoryRow[] = [];
  for (const [file, source] of files) {
    const threadLocal = /thread_local!\s*\{/g;
    let match: RegExpExecArray | null;
    while ((match = threadLocal.exec(source))) {
      const open = source.indexOf("{", match.index);
      const block = toolJobRustBlock(source, open);
      if (!block) break;
      rows.push({ file, line: source.slice(0, match.index).split("\n").length, text: match[0], owners: ownersOf(block.body) });
      threadLocal.lastIndex = block.end;
    }
    const locked = /(?:OnceLock|LazyLock)\s*<\s*(?:std::sync::)?Mutex\s*</g;
    while ((match = locked.exec(source))) {
      const start = source.lastIndexOf("static ", match.index);
      const initializer = source.indexOf("=", match.index);
      const end = initializer < 0 ? -1 : source.indexOf(";", initializer);
      const declaration = start < 0 || end < 0 ? "" : source.slice(start, end + 1);
      rows.push({ file, line: source.slice(0, match.index).split("\n").length, text: match[0], owners: ownersOf(declaration) });
    }
  }
  return rows;
}

/** 🗄️ Exempts only the shared, executable operation/generation registry contract. Bespoke arrays,
 * registries, aliases, and annotation-only claims remain blockers until they use this authority. */
function toolJobGlobalPayloadStoreIsSharedFixedAuthority(row: GlobalPayloadStoreInventoryRow): boolean {
  return (
    row.owners.length > 0 &&
    row.owners.every(
      (owner) =>
        owner.kind === "fixed-operation-registry" &&
        /(?:OnceLock\s*<\s*(?:std::sync::)?Mutex\s*<|RefCell\s*<)\s*semio_framework_job::FixedOperationRegistry\s*</.test(owner.rustType),
    )
  );
}

/** 🎯️ Enumerates macro and ordinary builder registrations without trusting a manifest disposition. */
function toolJobStaticRows(files: ReadonlyMap<string, string>): ToolJobStaticRow[] {
  const rows: ToolJobStaticRow[] = [];
  const constants = new Map<string, string>();
  for (const source of files.values()) {
    for (const match of source.matchAll(/(?:pub(?:\([^)]*\))?\s+)?const\s+([A-Z][A-Z0-9_]*)\s*:\s*&(?:'static\s+)?str\s*=\s*"([^"]+)"/g)) constants.set(match[1]!, match[2]!);
  }
  for (const [file, source] of files) {
    const invocation = /^\s*(?:[A-Za-z_][A-Za-z0-9_]*::)*app_commands!\s*\{/gm;
    let match: RegExpExecArray | null;
    while ((match = invocation.exec(source))) {
      const block = toolJobRustBlock(source, source.indexOf("{", match.index));
      if (!block) break;
      const row = /^\s*"([^"]+)"(?:\s+as\s+"[^"]+")?\s*=>/gm;
      let item: RegExpExecArray | null;
      while ((item = row.exec(block.body))) rows.push({ file, id: item[1]!, source: "macro" });
      invocation.lastIndex = block.end;
    }
    const typedVariants = /^\s*[A-Za-z_][A-Za-z0-9_]*_command_variants!\s*\{/gm;
    while ((match = typedVariants.exec(source))) {
      const block = toolJobRustBlock(source, source.indexOf("{", match.index));
      if (!block) break;
      const row = /^\s*[A-Za-z_][A-Za-z0-9_]*\s*=\s*(?:"([^"]+)"|(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*))\s*,?/gm;
      let item: RegExpExecArray | null;
      while ((item = row.exec(block.body))) {
        const id = item[1] ?? constants.get(item[2] ?? "");
        if (id) rows.push({ file, id, source: "literal" });
      }
      typedVariants.lastIndex = block.end;
    }
    const literal = /\.(?:mutation|operation|view_action|shell_action)\(\s*"([^"]+)"|\.action_with\(\s*ActionDefinition(?:\s*\{[\s\S]{0,300}?\.\.)?::(?:new_catalog|bounded_catalog|new)\(\s*"([^"]+)"|\.(?:app_command|command_with)\(\s*CommandDefinition::(?:new_catalog|bounded_catalog|new)\(\s*"([^"]+)"/g;
    while ((match = literal.exec(source))) rows.push({ file, id: match[1] ?? match[2] ?? match[3]!, source: "literal" });
  }
  const unique = new Map<string, ToolJobStaticRow>();
  for (const row of rows) unique.set(`${row.file}\0${row.id}`, row);
  return [...unique.values()].sort((left, right) => left.file.localeCompare(right.file) || left.id.localeCompare(right.id));
}

function toolJobPublicationContracts(
  source: string,
  factoryBody: string,
  strings: ReadonlyMap<string, string>,
): Map<string, ToolJobPublicationLane[]> | undefined {
  const expression = factoryBody.match(/const\s+PUBLICATION_CONTRACTS\s*:\s*&'static\s*\[\s*(?:semio_framework_plugin::)?ArtifactToolPublicationContract\s*\]\s*=\s*([^;]+);/s)?.[1]?.trim();
  if (!expression) return undefined;
  const constant = expression.match(/^(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*)$/)?.[1];
  const declaration = constant ? source.search(new RegExp(`(?:pub(?:\\([^)]*\\))?\\s+)?const\\s+${constant}\\s*:\\s*&(?:'static\\s+)?\\[\\s*(?:semio_framework_plugin::)?ArtifactToolPublicationContract\\s*\\]\\s*=`)) : -1;
  const open = declaration < 0 ? -1 : source.indexOf("[", source.indexOf("=", declaration));
  const array = open < 0 ? undefined : toolJobRustArray(source, open);
  const contracts = constant ? array?.body : expression;
  if (!contracts) return undefined;
  const result = new Map<string, ToolJobPublicationLane[]>();
  const row = /(?:semio_framework_plugin::)?ArtifactToolPublicationContract\s*\{\s*tool_id:\s*(?:"([^"]+)"|(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*))\s*,\s*lanes:\s*&\[([^\]]*)\]\s*\}/g;
  let match: RegExpExecArray | null;
  while ((match = row.exec(contracts))) {
    const toolId = match[1] ?? strings.get(match[2] ?? "");
    const lanes = [...match[3]!.matchAll(/(?:semio_framework_plugin::)?ArtifactToolPublicationLane::(HostOnly|Artifact|Config|Draft|Presence|Transient|Child)/g)].map((lane) => lane[1] as ToolJobPublicationLane);
    if (!toolId || result.has(toolId) || lanes.length === 0 || new Set(lanes).size !== lanes.length || (lanes.includes("HostOnly") && lanes.length !== 1)) return undefined;
    result.set(toolId, lanes);
  }
  return result.size > 0 ? result : undefined;
}

function toolJobPublicationAuthorityReady(ownerBody: string, lanes: readonly ToolJobPublicationLane[]): boolean {
  const factory = (name: string) => {
    const start = ownerBody.search(new RegExp(`fn\\s+${name}\\s*\\(`));
    const open = start < 0 ? -1 : ownerBody.indexOf("{", start);
    const body = open < 0 ? undefined : toolJobRustBlock(ownerBody, open);
    return !!body && /\bSome\s*\(/.test(body.body);
  };
  return lanes.every((lane) => {
    if (lane === "HostOnly") return true;
    if (lane === "Child") return false;
    if (lane === "Artifact") return factory("build_artifact_store_one_item_preparation_factory");
    if (lane === "Config") return factory("build_config_store_one_item_preparation_factory");
    if (lane === "Draft") return factory("build_draft_store_one_item_preparation_factory");
    if (lane === "Presence") return factory("build_presence_store_one_item_preparation_factory") && factory("build_presence_local_root_retirement_factory");
    return factory("build_transient_store_one_item_preparation_factory") && factory("build_transient_local_root_retirement_factory");
  });
}

/** 🧩️ Enumerates only command rows backed by an explicitly registered app-owned factory and builder. */
function toolJobAppOwnedRows(files: ReadonlyMap<string, string>): ToolJobAppOwnedRow[] {
  const stringConstants = new Map<string, Map<string, string>>();
  const listConstants = new Map<string, Map<string, string[]>>();
  for (const [file, source] of files) {
    const strings = new Map<string, string>();
    for (const match of source.matchAll(/(?:pub(?:\([^)]*\))?\s+)?const\s+([A-Z][A-Z0-9_]*)\s*:\s*&(?:'static\s+)?str\s*=\s*"([^"]+)"/g)) strings.set(match[1]!, match[2]!);
    stringConstants.set(file, strings);
    const lists = new Map<string, string[]>();
    for (const match of source.matchAll(/(?:pub(?:\([^)]*\))?\s+)?const\s+([A-Z][A-Z0-9_]*)\s*:\s*&(?:'static\s+)?\[\s*&(?:'static\s+)?str\s*\]\s*=\s*&\[([^\]]*)\]\s*;/gs)) {
      const ids: string[] = [];
      for (const item of match[2]!.split(",")) {
        const literal = item.match(/"([^"]+)"/)?.[1];
        const constant = item.trim().match(/^(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*)$/)?.[1];
        const id = literal ?? strings.get(constant ?? "");
        if (id) ids.push(id);
      }
      lists.set(match[1]!, ids);
    }
    listConstants.set(file, lists);
  }
  const ownerFiles = new Map<string, { file: string; body: string }>();
  for (const [file, source] of files) {
    const owner = /impl\s+(?:semio_framework_plugin::)?(ArtifactEditor|ArtifactApp)\s+for\s+([A-Za-z_][A-Za-z0-9_]*)\s*\{/g;
    let match: RegExpExecArray | null;
    while ((match = owner.exec(source))) {
      const open = source.indexOf("{", match.index);
      const block = toolJobRustBlock(source, open);
      if (!block) break;
      ownerFiles.set(`${match[1]}\0${match[2]}`, { file, body: block.body });
      owner.lastIndex = block.end;
    }
  }
  const production = [...files.values()].join("\n");
  const rows: ToolJobAppOwnedRow[] = [];
  for (const [factoryFile, source] of files) {
    const implementation = /impl\s+(?:semio_framework_plugin::)?ArtifactOwnedToolJobFactory\s+for\s+([A-Za-z_][A-Za-z0-9_]*)\s*\{/g;
    let match: RegExpExecArray | null;
    while ((match = implementation.exec(source))) {
      const factory = match[1]!;
      const open = source.indexOf("{", match.index);
      const block = toolJobRustBlock(source, open);
      if (!block) break;
      implementation.lastIndex = block.end;
      const ownerExpression = block.body.match(/type\s+Owner\s*=\s*([^;]+)\s*;/)?.[1]?.replaceAll(/\s+/g, "");
      const editorOwner = ownerExpression?.match(/^(?:semio_framework_plugin::)?EditorApp<([A-Za-z_][A-Za-z0-9_]*)>$/)?.[1];
      const directOwner = editorOwner ? undefined : ownerExpression?.match(/^(?:semio_framework_plugin::)?([A-Za-z_][A-Za-z0-9_]*)$/)?.[1];
      const ownerTypeName = editorOwner ?? directOwner;
      const toolExpression = block.body.match(/const\s+TOOL_IDS\s*:\s*&'static\s*\[\s*&'static\s+str\s*\]\s*=\s*([^;]+);/s)?.[1]?.trim();
      const owner = editorOwner ? ownerFiles.get(`ArtifactEditor\0${editorOwner}`) : directOwner ? ownerFiles.get(`ArtifactApp\0${directOwner}`) : undefined;
      const registered = new RegExp(`registry\\.register\\(\\s*(?:[A-Za-z_][A-Za-z0-9_]*::)*${factory}::new\\(`).test(production);
      const concrete = new RegExp(`impl\\s+(?:semio_framework::)?ToolJobFactory\\s+for\\s+${factory}\\s*\\{`).test(source) && source.includes("fn create_job") && source.includes("fn execution_contract");
      const builder = !!owner && /fn\s+build_tool_job\s*\([^)]*request/s.test(owner.body) && owner.body.includes("request");
      if (!owner || !registered || !concrete || !builder || !toolExpression) continue;
      const localStrings = stringConstants.get(factoryFile) ?? new Map<string, string>();
      const localLists = listConstants.get(factoryFile) ?? new Map<string, string[]>();
      const ids = toolExpression.startsWith("&[")
        ? toolExpression
            .slice(2, toolExpression.lastIndexOf("]"))
            .split(",")
            .map((item) => item.match(/"([^"]+)"/)?.[1] ?? localStrings.get(item.trim().match(/(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*)/)?.[1] ?? ""))
            .filter((id): id is string => !!id)
        : localLists.get(toolExpression.match(/(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*)/)?.[1] ?? "") ?? [];
      const publication = toolJobPublicationContracts(source, block.body, localStrings);
      const exactPublication = !!publication && publication.size === ids.length && ids.every((toolId) => publication.has(toolId));
      for (const toolId of ids) {
        const publicationLanes = exactPublication ? publication!.get(toolId)! : [];
        rows.push({
          ownerFile: owner.file,
          factoryFile,
          ownerTypeName,
          factory,
          toolId,
          publicationLanes,
          publicationReady: exactPublication && toolJobPublicationAuthorityReady(owner.body, publicationLanes),
        });
      }
    }
  }
  const unique = new Map<string, ToolJobAppOwnedRow>();
  for (const row of rows) unique.set(`${row.ownerFile}\0${row.toolId}`, row);
  return [...unique.values()].sort((left, right) => left.ownerFile.localeCompare(right.ownerFile) || left.toolId.localeCompare(right.toolId));
}

/** 🔒️ Reads exact explicit dispositions; constructors never count as proof. */
function toolJobDispositions(files: ReadonlyMap<string, string>): Map<string, string> {
  const result = new Map<string, string>();
  const constants = new Map<string, string>();
  for (const source of files.values()) {
    for (const match of source.matchAll(/(?:pub(?:\([^)]*\))?\s+)?const\s+([A-Z][A-Z0-9_]*)\s*:\s*&str\s*=\s*"([^"]+)"/g)) constants.set(match[1]!, match[2]!);
  }
  for (const [file, source] of files) {
    const explicit = /\.action_interactive_job\(\s*(?:"([^"]+)"|(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*))\s*,\s*(?:semio_framework_plugin::)?InteractiveJobClassification::(Migrated|BatchOnlyPendingRewrite|ForbiddenFromUi|Deleted)\s*\)/g;
    let match: RegExpExecArray | null;
    while ((match = explicit.exec(source))) {
      const id = match[1] ?? constants.get(match[2] ?? "");
      if (id) result.set(`${file}\0${id}`, match[3]!);
    }
  }
  return result;
}

type ToolJobProof = {
  sourceFile: string;
  ownerFile: string;
  ownerTypeName: string;
  controllerId: string;
  factory: string;
  factoryType?: string;
  toolId: string;
  documentSchema: string;
  execution: "bounded" | "resumable";
  values: readonly number[];
};

/** 📐️ Reads only owner-local typed bounded-first-step proof catalogs. */
function toolJobProofs(files: ReadonlyMap<string, string>): ToolJobProof[] {
  const proofs: ToolJobProof[] = [];
  const valuesOf = (source: string): number[] => source.split(",").map((value) => Number(value.trim().replaceAll("_", "")));
  const validValues = (values: readonly number[]) => (values.length === 5 || values.length === 7) && values.every((value) => Number.isFinite(value) && value > 0) && values[4]! < 8_000;
  for (const [sourceFile, source] of files) {
    const invocation = /(?:semio_framework_plugin::)?bounded_first_step_tool_proofs!\s*\{/g;
    let match: RegExpExecArray | null;
    while ((match = invocation.exec(source))) {
      const block = toolJobRustBlock(source, source.indexOf("{", match.index));
      if (!block) break;
      const header = block.body.match(/owner:\s*([^,]+),\s*owner_file:\s*"([^"]+)",\s*controller:\s*"([^"]+)",\s*document_schema:\s*"([^"]+)",\s*factory:\s*"([^"]+)"/s);
      if (header) {
        const factoryType = block.body.match(/factory_type:\s*([^,]+),/)?.[1]?.replaceAll(/\s+/g, "");
        const common = { sourceFile, ownerFile: header[2]!, ownerTypeName: header[1]!.replaceAll(/\s+/g, ""), controllerId: header[3]!, documentSchema: header[4]!, factory: header[5]!, factoryType };
        const mappedRows = [...block.body.matchAll(/"([^"]+)"\s*=>\s*semio_framework::ToolExecutionContract::(bounded_first_step|resumable)\(([^)]*)\)/g)];
        for (const row of mappedRows) {
          const values = valuesOf(row[3]!);
          if (validValues(values)) proofs.push({ ...common, toolId: row[1]!, execution: row[2] === "resumable" ? "resumable" : "bounded", values });
        }
        if (mappedRows.length === 0) {
          const sharedContract = block.body.match(/contract:\s*semio_framework::ToolExecutionContract::(bounded_first_step|resumable)\(([^)]*)\)/);
          const sharedTools = block.body.match(/tools:\s*\[([^\]]*)\]/s);
          const values = valuesOf(sharedContract?.[2] ?? "");
          if (sharedTools && validValues(values)) {
            for (const tool of sharedTools[1]!.matchAll(/"([^"]+)"/g)) proofs.push({ ...common, toolId: tool[1]!, execution: sharedContract?.[1] === "resumable" ? "resumable" : "bounded", values });
          }
        }
      }
      invocation.lastIndex = block.end;
    }
  }
  return proofs;
}

/** 🚧 Rejects resumable cursors that spend their yields only scanning inputs and then call the
 * original one-shot reducer. Such a route moves the latency spike but does not split it. */
function toolJobScanThenMonolithRows(files: ReadonlyMap<string, string>, proofs: readonly ToolJobProof[]): { file: string; id: string; helper: string }[] {
  const rows: { file: string; id: string; helper: string }[] = [];
  for (const [file, source] of files) {
    const resumable = proofs.filter((proof) => proof.sourceFile === file && proof.execution === "resumable");
    if (resumable.length === 0) continue;
    const implementation = /impl(?:<[^>]+>)?\s+(?:semio_framework_plugin::retained_command::)?ArtifactCommandWork<[^{}]+>\s+for\s+[^\s<{]+(?:<[^>{]+>)?\s*\{/g;
    let match: RegExpExecArray | null;
    while ((match = implementation.exec(source))) {
      const block = toolJobRustBlock(source, source.indexOf("{", match.index));
      if (!block) break;
      implementation.lastIndex = block.end;
      if (!block.body.includes("ArtifactCommandWorkStep::Progress") || !block.body.includes("command-scan")) continue;
      const called = [...block.body.matchAll(/\b([a-z_][a-z0-9_]*)\s*\(/g)].map((call) => call[1]!);
      const helper = called.find((name) => {
        const declaration = new RegExp(`(?:^|\\n)\\s*fn\\s+${name}\\s*\\(`, "m").exec(source);
        if (!declaration) return false;
        const open = source.indexOf("{", declaration.index);
        const body = open < 0 ? undefined : toolJobRustBlock(source, open);
        return !!body && /(?:command\s*)?\.dispatch\s*\(/.test(body.body);
      });
      if (!helper && !/(?:command\s*)?\.dispatch\s*\(/.test(block.body)) continue;
      for (const proof of resumable) rows.push({ file, id: proof.toolId, helper: helper ?? "inline-dispatch" });
      break;
    }
  }
  return rows.sort((left, right) => left.file.localeCompare(right.file) || left.id.localeCompare(right.id));
}

function toolJobProofIdentity(proof: ToolJobProof): string {
  return `${proof.ownerFile}\0${proof.ownerTypeName}\0${proof.controllerId}\0${proof.factory}\0${proof.factoryType ?? ""}\0${proof.toolId}\0${proof.documentSchema}.tool-command.v1`;
}

//#region 🧭️ConcreteFactoryResolution
/** 🧭️ Resolves one crate module through its package's explicit taxonomy declarations. */
function toolJobFactoryModuleFile(files: ReadonlyMap<string, string>, ownerFile: string, modulePath: string): string | undefined {
  const candidates = new Set<string>();
  const visit = (source: string, directory: string, prefix: string): void => {
    const declaration = /#\[path\s*=\s*"([^"]+)"\]\s*(?:pub(?:\([^)]*\))?\s+)?mod\s+([A-Za-z_][A-Za-z0-9_]*)\s*([;{])/g;
    let match: RegExpExecArray | null;
    while ((match = declaration.exec(source))) {
      const target = posix.normalize(posix.join(directory, match[1]!));
      const name = `${prefix}::${match[2]}`;
      if (match[3] === ";") {
        const exportedComponent = prefix === modulePath && match[2] === "component" && /pub\s+use\s+component::\*\s*;/.test(source);
        if ((name === modulePath || exportedComponent) && files.has(target)) candidates.add(target);
      } else {
        const block = toolJobRustBlock(source, source.indexOf("{", match.index));
        if (!block) return;
        visit(block.body, target, name);
        declaration.lastIndex = block.end;
      }
    }
  };
  for (const [file, source] of files) {
    if (!file.endsWith("/🦀️.rs")) continue;
    const packageBoundary = file.lastIndexOf("/📦️packages/");
    if (packageBoundary < 0 || !ownerFile.startsWith(`${file.slice(0, packageBoundary)}/`)) continue;
    visit(source, posix.dirname(file), "crate");
  }
  return candidates.size === 1 ? [...candidates][0] : undefined;
}

/** 🧬️ Resolves a compiler type token, including an explicit import alias, to one concrete source type. */
function toolJobFactoryType(files: ReadonlyMap<string, string>, ownerFile: string, reference: string): { file: string; name: string } | undefined {
  if (!/^(?:crate::)?[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*$/.test(reference)) return undefined;
  const ownerSource = files.get(ownerFile) ?? "";
  let path = reference;
  if (!reference.includes("::")) {
    const imports = [...ownerSource.matchAll(/(?:^|\n)\s*use\s+(crate(?:::[A-Za-z_][A-Za-z0-9_]*)+)(?:\s+as\s+([A-Za-z_][A-Za-z0-9_]*))?\s*;/g)]
      .filter((entry) => (entry[2] ?? entry[1]!.split("::").at(-1)) === reference);
    const local = new RegExp(`(?:struct|enum)\\s+${reference}\\b`).test(ownerSource);
    if (local && imports.length === 0) return { file: ownerFile, name: reference };
    if (local || imports.length !== 1) return undefined;
    path = imports[0]![1]!;
  }
  if (!path.startsWith("crate::")) return undefined;
  const name = path.split("::").at(-1)!;
  const file = toolJobFactoryModuleFile(files, ownerFile, path.slice(0, -(name.length + 2)));
  return file ? { file, name } : undefined;
}

/** 🔐️ Binds the compiler witness to its actual factory, exact owner, route, and live registration site. */
function toolJobConcreteFactoryExact(files: ReadonlyMap<string, string>, proof: ToolJobProof, ownerBody: string): boolean {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(proof.factory) || !proof.factoryType) return false;
  const witness = toolJobFactoryType(files, proof.ownerFile, proof.factoryType);
  if (!witness || witness.name !== proof.factory) return false;
  const source = files.get(witness.file) ?? "";
  const implementation = (trait: string, namespace: string): string | undefined => {
    const start = source.search(new RegExp(`impl\\s+(?:${namespace}::)?${trait}\\s+for\\s+${witness.name}\\s*\\{`));
    return start < 0 ? undefined : toolJobRustBlock(source, source.indexOf("{", start))?.body;
  };
  const factory = implementation("ToolJobFactory", "semio_framework");
  const owned = implementation("ArtifactOwnedToolJobFactory", "semio_framework_plugin");
  const canonicalOwner = (owner: string) => owner.replaceAll(/\s+/g, "").replace(/^semio_framework_plugin::/, "");
  if (!factory || !owned || !factory.includes("type Job =") || !/fn\s+create_job\s*\(/.test(factory) || !/fn\s+execution_contract\s*\(/.test(factory)
    || canonicalOwner(owned.match(/type\s+Owner\s*=\s*([^;]+);/)?.[1] ?? "") !== canonicalOwner(proof.ownerTypeName)) return false;
  const listExpression = owned.match(/const\s+TOOL_IDS\s*:[^=]+=\s*([^;]+);/)?.[1]?.trim();
  const listName = listExpression?.match(/^(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Z][A-Z0-9_]*)$/)?.[1];
  const list = listName ? source.match(new RegExp(`const\\s+${listName}\\s*:[^=]+=\\s*&\\[([^\\]]*)\\]`))?.[1] : listExpression;
  if (!list) return false;
  const strings = new Map([...source.matchAll(/const\s+([A-Z][A-Z0-9_]*)\s*:\s*&(?:'static\s+)?str\s*=\s*"([^"]+)"/g)].map((row) => [row[1]!, row[2]!]));
  const toolIds = [...list.matchAll(/"([^"]+)"|\b([A-Z][A-Z0-9_]*)\b/g)].map((row) => row[1] ?? strings.get(row[2]!));
  if (!toolIds.includes(proof.toolId)) return false;
  const registeredIn = (body: string, file: string) => [...body.matchAll(/registry\.register\(\s*((?:[A-Za-z_][A-Za-z0-9_]*::)*[A-Za-z_][A-Za-z0-9_]*)::new\s*\(/g)].some((entry) => {
    const registered = toolJobFactoryType(files, file, entry[1]!);
    return registered?.file === witness.file && registered.name === witness.name;
  });
  if (registeredIn(ownerBody, proof.ownerFile)) return true;
  return [...ownerBody.matchAll(/(crate(?:::[A-Za-z_][A-Za-z0-9_]*)+)::register\(registry\)/g)].some((entry) => {
    const file = toolJobFactoryModuleFile(files, proof.ownerFile, entry[1]!);
    if (file !== witness.file) return false;
    const delegated = source.search(/\bfn\s+register\s*\(/);
    const body = delegated < 0 ? undefined : toolJobRustBlock(source, source.indexOf("{", delegated))?.body;
    return !!body && registeredIn(body, witness.file);
  });
}
/** 🧪️ Runs strict language-neutral cross-file factory laws and hostile module substitutions. */
export function toolJobOwnerFactoryResolutionSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🧵️retained-command");
  const schema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️owner-factory-resolution.schema.json"), "utf8"));
  const fixture = JSON.parse(readFileSync(join(base, "🧪️fixtures/🔣️owner-factory-resolution.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  if (!validate(fixture)) throw new Error(`owner factory fixture schema: ${JSON.stringify(validate.errors)}`);
  const compilerProof = toolJobProofs(new Map([[fixture.ownerFile, fixture.ownerSource]]));
  if (compilerProof.length !== 1 || compilerProof[0]?.factoryType !== fixture.factoryType) throw new Error("owner factory compiler witness field was not parsed exactly");
  for (const hostile of [{ ...fixture, extra: true }, { ...fixture, cases: [{ ...fixture.cases[0], extra: true }] }, { ...fixture, cases: [{ ...fixture.cases[0], accepted: "true" }] }]) {
    if (validate(hostile)) throw new Error("owner factory strict schema accepted an adversarial fixture");
  }
  for (const law of fixture.cases) {
    const candidate = { ...fixture };
    if (law.from && !candidate[law.target].includes(law.from)) throw new Error(`owner factory missing hostile anchor ${law.id}`);
    candidate[law.target] = candidate[law.target].replace(law.from, law.to);
    const files = new Map<string, string>([[candidate.ownerFile, candidate.ownerSource], [candidate.factoryFile, candidate.factorySource], [candidate.glueFile, candidate.glueSource]]);
    const failures = toolJobProofCatalogFailures(files, toolJobStaticRows(files), toolJobDispositions(files), toolJobProofs(files));
    if ((failures.length === 0) !== law.accepted) throw new Error(`owner factory ${law.id}: ${JSON.stringify(failures)}`);
  }
  return fixture.cases.length + 3;
}

/** 🧪️ Compares the runtime join fixture with an independent Ajv exact-authority oracle and hostile source variants. */
export function toolJobFactoryProofJoinSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️tool-factory-proof.json"), "utf8"));
  const schema = JSON.parse(readFileSync(join(base, "🧬️tool-factory-proof.schema.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const ajv = new Ajv({ strict: true, allErrors: true });
  const validate = ajv.compile(schema);
  if (!validate(fixture)) throw new Error(`factory runtime fixture schema: ${JSON.stringify(validate.errors)}`);
  const exact = { ownerType: "TestApp", controller: "s.test.synthetic@1/*#editor", documentSchema: "semio.test/v1", tool: "setLabel", factoryType: "TestRetainedCommandFactory", factoryTypeName: "plugin::TestRetainedCommandFactory", payloadSchema: "semio.test.retained-command.v1", executionContract: "resumable:4096:4:1:4096:7500:1:1", liveBusRegistration: true, factoryName: "TestRetainedCommandFactory", registered: true, unique: true };
  const oracle = ajv.compile({ const: exact });
  const field = { wrongType: "factoryType", sameOwnerDifferentFactory: "factoryType", wrongTypeName: "factoryTypeName", wrongFactory: "factoryName", wrongOwner: "ownerType", wrongController: "controller", wrongDocumentSchema: "documentSchema", wrongTool: "tool", wrongContract: "executionContract", wrongPayloadSchema: "payloadSchema", differentBus: "liveBusRegistration" };
  for (const law of fixture.cases) {
    const candidate: Record<string, unknown> = { ...exact };
    if (law.change === "missingType") delete candidate.factoryType;
    else if (law.change === "missingRegistration") candidate.registered = false;
    else if (law.change === "sentinel") { candidate.factoryName = "BoundedFirstStepCommandJobFactory"; delete candidate.factoryType; delete candidate.factoryTypeName; }
    else if (law.change === "duplicate") candidate.unique = false;
    else if (law.change !== "none") candidate[field[law.change as keyof typeof field]] = "other-authority";
    if (oracle(candidate) !== law.accepted) throw new Error(`factory runtime oracle disagrees for ${law.id}`);
  }
  const source = readFileSync(join(base, "🦀️.rs"), "utf8");
  if (!toolJobRuntimeProofQualified(source)) throw new Error("production runtime factory join is not exact");
  const hostile = [
    "A::register_tool_job_factories(&mut app_tool_registry)",
    "row.factory_type_id == Some(registration.factory_type_id)",
    "row.factory_type_name == Some(registration.factory_type_name)",
    "registration.owner == owner",
    "registration.key.controller_id == runtime_controller_id",
    "registration.key.tool_id == row.tool_id",
    "registration.contract == row.contract",
    "bus.admit_exact_wire(runtime_controller_id, row.tool_id, &registration.schema_id, &[])",
    "QualifiedToolProof::AppOwned(registration.clone()).admits::<A>(&admission)",
    "proof.with_factory_type::<$owner, $factory_type>()",
    "&& registered.is_none()",
  ];
  for (const anchor of hostile) {
    if (!source.includes(anchor)) throw new Error(`factory runtime hostile anchor missing: ${anchor}`);
    if (toolJobRuntimeProofQualified(source.replaceAll(anchor, "unqualified_authority"))) throw new Error(`factory runtime accepts missing authority: ${anchor}`);
  }
  return fixture.cases.length + hostile.length + 1;
}

/** 🧪️ Scans every production app catalog for an exact compiler factory witness and rejects custom-covered generic rows. */
export function toolJobFactoryProofActivationScan(root: string): { owners: number; customRows: number; genericRows: number; failures: string[] } {
  const sources = new Map(policyAllRustFiles(root).filter((file) => file.includes("✏️s/🔌️plugins/") && !file.includes("/🧪️tests/")).map((file) => [file, toolJobProductionProtocolSource(policyReadFileSafe(root, file))]));
  const proofs = toolJobProofs(sources);
  const failures = toolJobProofCatalogFailures(sources, toolJobStaticRows(sources), toolJobDispositions(sources), proofs).filter((failure) => failure.startsWith("forged bounded reducer factory or compiler witness"));
  return { owners: new Set(proofs.map((proof) => proof.ownerFile)).size, customRows: proofs.filter((proof) => proof.factoryType !== undefined).length, genericRows: proofs.filter((proof) => proof.factoryType === undefined).length, failures };
}

//#region ⏱️MicrosecondBudgetLaws
/** ⏱️ Cross-checks exact microsecond deadlines with strict Ajv and independent BigInt arithmetic. */
function toolJobMicrosecondWorkerExact(pluginRaw: string, jobRaw: string, traceRaw: string): boolean {
  const plugin = toolJobProductionSource(pluginRaw);
  const job = toolJobProductionSource(jobRaw);
  const trace = toolJobProductionSource(traceRaw);
  const body = (source: string, marker: string): string | undefined => {
    if (source.split(marker).length !== 2) return undefined;
    return toolJobRustBlock(source, source.indexOf("{", source.indexOf(marker)))?.body;
  };
  const setup = toolJobRetainedDispatchSetup(plugin);
  const operation = body(plugin, "impl<A: ArtifactApp> semio_framework_job::InteractiveJob for TypedCommandFullOperationJob<A>");
  const driver = body(job, "fn drive_step_with_payload_ledger<");
  const worker = body(job, "fn drive_worker_job_authority<");
  const duration = body(job, "pub fn from_duration(");
  const clock = body(job, "pub fn default_now_us(");
  const preflight = "if budget.fuel == 0 || now_us().is_none_or(|now_us| now_us >= budget.deadline_us)";
  return toolJobMountedDispatchOneTurnExact(plugin) && !!setup && !!operation && !!driver && !!worker && !!duration && !!clock
    && /step_budget_us:\s*u64::from\(admission\.proof\.contract\(\)\.max_step_micros\),/.test(setup)
    && setup.includes("now_us: semio_framework_job::default_now_us,")
    && setup.includes("fuel_per_step: admission.proof.contract().max_work_units_per_step")
    && setup.includes("ArtifactOutputChunks::new(admission.proof.contract().max_output_bytes)")
    && ["self.decoded_items > self.contract.max_decoded_items", "self.contract.max_work_units_per_step == 0", "self.contract.max_output_bytes"].every((token) => operation.includes(token))
    && plugin.includes("TypedOperationResultPageWriter") && plugin.includes("one typed-operation result exceeds its fixed incremental encoder authority")
    && duration.includes("start_us.checked_add(duration_us).map(")
    && worker.includes("(params.now_us)().and_then(|start_us| StepBudget::from_duration(config.fuel_per_step, start_us, config.step_budget_us))")
    && worker.includes("invalid deadline retains its pre-admitted terminal fault page")
    && driver.includes(preflight) && driver.indexOf(preflight) < driver.indexOf("job.step(&mut cx)")
    && clock.includes("semio_framework_trace::try_now_us()")
    && trace.includes("fn default_clock_us() -> Option<u64> { None }")
    && trace.includes("elapsed().as_micros()).ok()");
}

export function toolJobCooperativeMaintenanceSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🔨️modules/⏳️async/⏱️cooperative");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️fixture/🔣️.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(JSON.parse(readFileSync(join(base, "🧬️schema.json"), "utf8")));
  if (!validate(fixture)) throw new Error(`cooperative maintenance schema: ${JSON.stringify(validate.errors)}`);
  const weights = new Map([["Maintenance", 1], ["Background", 2], ["UserVisible", 4], ["Timer", 3], ["Interactive", 8]]);
  const seen = new Set<string>();
  for (const law of fixture.cases) {
    const cost = BigInt(fixture.unitCost), weight = BigInt(law.weight);
    const turns = Number((cost + weight - 1n) / weight);
    if (seen.has(law.lane) || weights.get(law.lane) !== law.weight || turns !== law.selected.length || turns !== law.deficits.length) throw new Error(`cooperative maintenance exact lane: ${law.lane}`);
    seen.add(law.lane);
    for (let turn = 1; turn <= turns; turn++) {
      const accrued = BigInt(turn) * weight;
      if (law.deficits[turn - 1] !== Number(accrued % cost) || law.selected[turn - 1] !== (accrued >= cost)) throw new Error(`cooperative maintenance arithmetic oracle: ${law.lane}/${turn}`);
    }
  }
  for (const mutation of [{ unitCost: 9 }, { synchronousDrain: true }]) {
    if (validate({ ...fixture, ...mutation })) throw new Error("cooperative maintenance accepted changed grant or unknown drain");
  }
  return fixture.cases.length + 2;
}

export function toolJobTelemetryContentionSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🔨️modules/⏱️trace/⏱️clock");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️contention.json"), "utf8"));
  const schema = JSON.parse(readFileSync(join(base, "🧬️contention.schema.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  if (!validate(fixture)) throw new Error(`telemetry contention schema: ${JSON.stringify(validate.errors)}`);
  const ids = new Set<string>();
  for (const law of fixture.cases) {
    if (ids.has(law.id)) throw new Error(`duplicate telemetry contention law: ${law.id}`);
    ids.add(law.id);
    if (law.violationRetained !== (law.callback === "watchdog") || law.returnedEvent !== (law.callback === "event")) throw new Error(`telemetry exact authority oracle: ${law.id}`);
    if (law.callback === "event" ? law.lock !== "event" : law.callback === "timer" ? law.lock !== "site" : !["site", "violation"].includes(law.lock)) throw new Error(`telemetry contention owner oracle: ${law.id}`);
  }
  for (const change of [{ returnsWhileHeld: false }, { unboundedFallback: true }]) {
    if (validate({ ...fixture, cases: [{ ...fixture.cases[0], ...change }, ...fixture.cases.slice(1)] })) throw new Error("telemetry contention schema accepted callback waiting or unknown authority");
  }
  for (const law of fixture.verdicts) {
    const clockFault = law.start === null || law.end === null ? "Missing" : BigInt(law.end) < BigInt(law.start) ? "Backward" : null;
    const fault = clockFault !== null || BigInt(law.end) - BigInt(law.start) >= 8_000n;
    if (clockFault !== law.clockFault || fault !== law.fault) throw new Error(`exact callback verdict oracle: ${law.id}`);
  }
  return fixture.cases.length + fixture.verdicts.length + 2;
}

export function toolJobMicrosecondBudgetSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🔨️modules/🧵️job/⏱️budget");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️fixture/🔣️.json"), "utf8"));
  const schema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  if (!validate(fixture)) throw new Error(`microsecond budget schema: ${JSON.stringify(validate.errors)}`);
  const maximum = (1n << 64n) - 1n;
  for (const law of fixture.cases) {
    const sum = BigInt(law.start) + BigInt(law.grant);
    const deadline = sum > maximum ? null : sum.toString();
    if (deadline !== law.deadline) throw new Error(`microsecond checked deadline: ${law.id}`);
    const expired = law.samples.map((sample: string) => deadline === null || BigInt(sample) >= BigInt(deadline));
    const yielded = expired.map((value: boolean) => value || law.fuel === 0);
    if (JSON.stringify(expired) !== JSON.stringify(law.expired) || JSON.stringify(yielded) !== JSON.stringify(law.yielded)) throw new Error(`microsecond deadline boundary: ${law.id}`);
  }
  for (const change of [{ unit: "milliseconds" }, { extra: true }]) {
    if (validate({ ...fixture, ...change })) throw new Error("microsecond schema accepted a forged unit or field");
  }
  const clocks = JSON.parse(readFileSync(join(base, "🧪️clock.json"), "utf8"));
  const validateClocks = new Ajv({ strict: true, allErrors: true }).compile(JSON.parse(readFileSync(join(base, "🧬️schema/🔣️clock.json"), "utf8")));
  if (!validateClocks(clocks)) throw new Error(`host clock schema: ${JSON.stringify(validateClocks.errors)}`);
  for (const law of clocks.browser) {
    const [integer, fraction = ""] = law.milliseconds.split(".");
    const numerator = BigInt(integer) * 10n ** BigInt(fraction.length) + BigInt(fraction || "0");
    const exact = numerator * 1_000n / 10n ** BigInt(fraction.length);
    const expected = numerator < 0n || exact > maximum ? null : exact.toString();
    if (expected !== law.microseconds) throw new Error(`browser clock rational oracle: ${law.milliseconds}`);
    const actual = microsecondsFromMilliseconds(Number(law.milliseconds));
    if ((actual === null ? null : actual.toString()) !== expected) throw new Error(`browser clock conversion: ${law.milliseconds}`);
  }
  for (const law of clocks.wasi) {
    if ((BigInt(law.nanoseconds) <= maximum) !== law.accepted) throw new Error(`WASI checked nanoseconds: ${law.nanoseconds}`);
  }
  for (const law of clocks.installation) {
    const authority = new Map<string, string>();
    if (law.current !== null) authority.set("clock", law.current);
    const accepted = !authority.has("clock") || authority.get("clock") === law.requested;
    if (accepted) authority.set("clock", law.requested);
    if (accepted !== law.accepted || authority.get("clock") !== law.retained) throw new Error(`exact clock installation oracle: ${law.current}/${law.requested}`);
  }
  for (const law of clocks.watchdog) {
    if ((BigInt(law.elapsedMicroseconds) >= 8_000n) !== law.violated) throw new Error(`strict watchdog boundary oracle: ${law.elapsedMicroseconds}`);
  }
  for (const invalid of [Number.NaN, Number.POSITIVE_INFINITY]) if (microsecondsFromMilliseconds(invalid) !== null) throw new Error("invalid monotonic source was admitted");
  const binding = JSON.parse(readFileSync(join(base, "🧪️binding.json"), "utf8"));
  const validateBinding = new Ajv({ strict: true, allErrors: true }).compile(JSON.parse(readFileSync(join(base, "🧬️schema/🔣️binding.json"), "utf8")));
  if (!validateBinding(binding)) throw new Error(`microsecond binding schema: ${JSON.stringify(validateBinding.errors)}`);
  const plugin = readFileSync(join(WORKSPACE_ROOT, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🦀️.rs"), "utf8");
  const job = readFileSync(join(base, "../🦀️.rs"), "utf8");
  const trace = readFileSync(join(base, "../../⏱️trace/🦀️.rs"), "utf8");
  const mutations: Record<string, [number, string, string]> = {
    none: [0, "", ""],
    "wrong-helper": [0, "self.start_typed_command_operation(command, admission, meta, operation_id, None).await", "self.wrong_operation(command, admission, meta, operation_id, None).await"],
    "divided-grant": [0, "step_budget_us: u64::from(admission.proof.contract().max_step_micros),", "step_budget_us: u64::from(admission.proof.contract().max_step_micros) / 1_000,"],
    "rounded-grant": [0, "step_budget_us: u64::from(admission.proof.contract().max_step_micros),", "step_budget_us: u64::from(admission.proof.contract().max_step_micros).max(1_000),"],
    "coarse-clock": [0, "now_us: semio_framework_job::default_now_us,", "now_us: semio_framework_job::default_now_ms,"],
    "overflow-fallback": [1, "start_us.checked_add(duration_us)", "Some(start_us.saturating_add(duration_us))"],
    "expired-entry": [1, "if budget.fuel == 0 || now_us().is_none_or(|now_us| now_us >= budget.deadline_us)", "if budget.fuel == 0"],
    "synthetic-clock": [2, "fn default_clock_us() -> Option<u64> { None }", "fn default_clock_us() -> Option<u64> { Some(0) }"],
    "missing-output-limit": [0, "ArtifactOutputChunks::new(admission.proof.contract().max_output_bytes)", "ArtifactOutputChunks::new(u64::MAX)"],
  };
  const validBinding = new Ajv({ strict: true }).compile({ const: "none" });
  for (const law of binding.cases) {
    const [index, before, after] = mutations[law.mutation]!;
    const sources = [plugin, job, trace];
    if (law.mutation !== "none") {
      if (!sources[index]!.includes(before)) throw new Error(`microsecond hostile target is stale: ${law.mutation}`);
      sources[index] = sources[index]!.replaceAll(before, after);
    }
    if (validBinding(law.mutation) !== law.admitted || toolJobMicrosecondWorkerExact(sources[0]!, sources[1]!, sources[2]!) !== law.admitted) throw new Error(`microsecond exact worker binding: ${law.mutation}`);
  }
  return fixture.cases.length + clocks.browser.length + clocks.wasi.length + clocks.installation.length + clocks.watchdog.length + 4 + binding.cases.length * 2;
}
//#endregion ⏱️MicrosecondBudgetLaws

//#region 🗝️LatestWinsAuthorityLaws
/** 🧹️ Cross-checks CAD domain retirement byte counts independently of its Rust ownership cursor. */
export function cadPresenceRetirementSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "✏️s/🔌️plugins/📐️cad/🗿️artifacts/📐️cad/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/👥️presence");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️retirement.json"), "utf8"));
  const schema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️.schema.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  if (!validate(fixture)) throw new Error(`CAD presence retirement schema: ${JSON.stringify(validate.errors)}`);
  const counts = new Map<string, number>();
  for (const law of fixture.cases) {
    const bytes = [law.activeUtility, law.engagementStep, law.engagementPane].reduce((sum, part) => sum + (part === null ? 0 : Buffer.byteLength(part.unit.repeat(part.repeat), "utf8")), 0);
    if (counts.has(law.name) || bytes !== law.expectedBytes) throw new Error(`CAD presence byte oracle: ${law.name}`);
    counts.set(law.name, bytes);
  }
  for (const law of fixture.storeCases) {
    if (!counts.has(law.local) || law.peers.some((peer) => !counts.has(peer.presence))) throw new Error(`CAD presence unknown fixture root: ${law.name}`);
    const bytes = counts.get(law.local)! + law.peers.reduce((sum, peer) => sum + counts.get(peer.presence)! + Buffer.byteLength(peer.actor, "utf8"), 0);
    if (bytes !== law.expectedBytes) throw new Error(`CAD presence roster byte oracle: ${law.name}`);
  }
  for (const hostile of [{ ...fixture, grant: { maximumItems: 2, maximumBytes: 4096 } }, { ...fixture, grant: { maximumItems: 1, maximumBytes: 65536 } }]) {
    if (validate(hostile)) throw new Error("CAD presence schema accepted an enlarged production grant");
  }
  const storeBase = join(WORKSPACE_ROOT, "🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/👥️presence");
  const storeFixture = JSON.parse(readFileSync(join(storeBase, "🧪️retirement.json"), "utf8"));
  const storeSchema = JSON.parse(readFileSync(join(storeBase, "🧬️schema/🔣️.schema.json"), "utf8"));
  const validateStore = new Ajv({ strict: true, allErrors: true }).compile(storeSchema);
  if (!validateStore(storeFixture)) throw new Error(`presence Store retirement schema: ${JSON.stringify(validateStore.errors)}`);
  for (const law of storeFixture.cases) {
    if (law.expectedSnapshots !== law.peers.length + 1 || law.expectedActorBytes !== law.peers.reduce((sum, peer) => sum + Buffer.byteLength(peer.actor, "utf8"), 0)) throw new Error(`presence Store retirement oracle: ${law.name}`);
  }
  const distinctPeers = new Map<string, { actor: string }>([...storeFixture.overlap.first, ...storeFixture.overlap.second].map((peer) => [JSON.stringify(peer), peer]));
  if (distinctPeers.size !== storeFixture.overlap.expectedPeerSnapshots || [...distinctPeers.values()].reduce((sum, peer) => sum + Buffer.byteLength(peer.actor), 0) !== storeFixture.overlap.expectedActorBytes) throw new Error("presence overlapping-roster ownership oracle");
  const readerReturn = storeFixture.readerReturn;
  let readerAliases = 1;
  let registryAliases = 1;
  let returned = false;
  for (const event of readerReturn.eventOrder) {
    if (event === "reader-alias-released") readerAliases--;
    else if (event === "return-published") { if (readerAliases !== 0 || registryAliases !== 1) throw new Error("read return precedes exact alias release"); returned = true; }
    else if (event === "registry-owner-taken") { if (!returned || readerAliases !== 0) throw new Error("read registry take lacks exclusive payload authority"); }
    else if (event === "final-owner-retired") registryAliases--;
  }
  if (readerAliases !== 0 || registryAliases !== 0) throw new Error("read ownership oracle retains an alias");
  for (const hostile of [
    { ...storeFixture, readerReturn: { ...readerReturn, eventOrder: ["return-published", "reader-alias-released", "registry-owner-taken", "final-owner-retired"] } },
    { ...storeFixture, readerReturn: { ...readerReturn, contendedTransferPreservesUnreturned: false } },
    { ...storeFixture, readerReturn: { ...readerReturn, transferPublishesReturn: true } },
  ]) if (validateStore(hostile)) throw new Error("presence read schema accepted premature return or lost transfer authority");
  const storeSource = readFileSync(join(storeBase, "../🦀️.rs"), "utf8");
  const exactReadReturn = (source: string): boolean => {
    const block = (needle: string): string => { const start = source.indexOf(needle); return start < 0 ? "" : toolJobRustBlock(source, source.indexOf("{", start))?.body ?? ""; };
    const release = block("fn return_snapshot_read<T:");
    const transfer = block("fn into_typed<T:");
    const drop = release.indexOf("drop(owner.take());");
    const publish = release.indexOf("lease.return_now()");
    return drop >= 0 && publish > drop && release.indexOf("after_alias_release();") > drop
      && (source.match(/return_snapshot_read\(&mut self\.owner, &mut self\.lease, \|\| \{\}\)/g) ?? []).length === 4
      && transfer.includes("registry.try_take(lease.index, lease.generation)") && !transfer.includes("return_now")
      && transfer.includes("self.owner = Some(owner);") && transfer.includes("self.lease = Some(lease);");
  };
  if (!exactReadReturn(storeSource)) throw new Error("opaque snapshot read return/transfer lost its exact final-owner ordering");
  const readHostiles = [
    storeSource.replace("drop(owner.take());\n    after_alias_release();", "after_alias_release();"),
    storeSource.replace("let guard = match registry.try_take(lease.index, lease.generation)", "let _ = lease.return_now();\n        let guard = match registry.try_take(lease.index, lease.generation)"),
    storeSource.replace("self.lease = Some(lease);", "drop(lease);"),
  ];
  for (const hostile of readHostiles) if (hostile === storeSource || exactReadReturn(hostile)) throw new Error("opaque snapshot read source guard accepted a premature return or lost retained lease");
  const exactPeerRelease = (source: string): boolean => {
    const cursorStart = source.indexOf("impl<P: Send + Sync + 'static> PresencePeersRetirement<P>");
    const cursor = cursorStart < 0 ? "" : toolJobRustBlock(source, source.indexOf("{", cursorStart))?.body ?? "";
    const publicationStart = source.indexOf("impl<P: Send + Sync + 'static> PresencePeersPublication<P>");
    const publication = publicationStart < 0 ? "" : toolJobRustBlock(source, source.indexOf("{", publicationStart))?.body ?? "";
    return cursor.includes("*self.entry = Arc::into_inner(waiting)") && !cursor.includes("Arc::try_unwrap(waiting)")
      && cursor.includes("Arc::try_unwrap(root)") && cursor.includes("self.owned_root.as_mut()")
      && source.includes("*retirement.root = Some(previous)") && source.includes("presence peer entry requires exact final-owner retirement")
      && source.includes("actor: std::mem::ManuallyDrop<String>") && source.includes("presence: std::mem::ManuallyDrop<Option<Arc<P>>>")
      && !source.includes("impl<P> Clone for PresencePeersRoot<P>") && !source.includes("pub fn clone_aliases(&self)")
      && (publication.match(/PresencePeersRetirement::new\(PresencePeersRetiredEntries::one/g) ?? []).length === 2;
  };
  if (!exactPeerRelease(storeSource)) throw new Error("presence peer roots lost exact shared-entry final-owner retirement");
  const peerHostiles = [
    storeSource.replace("*self.entry = Arc::into_inner(waiting)", "*self.entry = Arc::try_unwrap(waiting).ok()"),
    storeSource.replace("*retirement.root = Some(previous)", "drop(previous)"),
    storeSource.replace("fn clone_aliases(&self)", "pub fn clone_aliases(&self)"),
  ];
  for (const hostile of peerHostiles) if (hostile === storeSource || exactPeerRelease(hostile)) throw new Error("presence peer guard accepted shared-owner waiting, implicit root drop, or public owner cloning");
  const replacements = storeFixture.localReplacements;
  const localOracle = new Ajv({ strict: true }).compile({ const: { ...replacements, capturedValues: replacements.values.slice(0, -1), expectedRetiredWhileOpen: replacements.values.length - 1, expectedFinalSnapshots: replacements.values.length } });
  if (!localOracle(replacements) || storeFixture.localCapture.expectedValueWhileOpen !== storeFixture.localCapture.value || !storeFixture.localCapture.expectedWorkerTerminal) throw new Error("presence local capture/replacement independent owner ledger");
  const retirementSource = readFileSync(join(storeBase, "♻️retirement/🦀️.rs"), "utf8");
  const cadSource = readFileSync(join(base, "♻️retirement/🦀️.rs"), "utf8");
  const exactLocal = (store: string, retirement: string, cad: string): boolean =>
    toolJobImmutableOperationRootsExact(store)
    && store.includes("pub base: ArtifactEphemeralBaseRead<P>")
    && store.includes("Presence(SnapshotRead<P>)")
    && store.includes("Arc::ptr_eq(installed, &root_retirement_factory)")
    && store.includes("previous.return_to_registry()")
    && retirement.includes("advance_returned_local(reads, &mut self.active_returned")
    && retirement.includes("self.active_returned_local.take()")
    && retirement.includes("presence store requires its exact detached terminal-empty owner before Drop")
    && retirement.includes("SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 }")
    && retirement.includes("MountedWorkerJobSession::try_new(job, params)")
    && retirement.includes("owner.maintenance_local_reads_step(1, 4096)")
    && cad.includes("*self.owned = Arc::into_inner(root)") && !cad.includes("Arc::try_unwrap(root)");
  if (!exactLocal(storeSource, retirementSource, cadSource)) throw new Error("presence local read, live return, detached close or final-owner authority is incomplete");
  const localHostiles = [
    [storeSource.replace("pub base: ArtifactEphemeralBaseRead<P>", "pub base: Arc<P>"), retirementSource, cadSource],
    [storeSource.replace("self.local_reads.try_issue(owner.clone())", "unregistered_read(owner.clone())"), retirementSource, cadSource],
    [storeSource.replace("Arc::ptr_eq(installed, &root_retirement_factory)", "true"), retirementSource, cadSource],
    [storeSource, retirementSource.replace("self.active_returned_local.take()", "None"), cadSource],
    [storeSource, retirementSource, cadSource.replace("Arc::into_inner(root)", "Arc::try_unwrap(root).ok()")],
  ];
  for (const [store, retirement, cad] of localHostiles) if (exactLocal(store, retirement, cad)) throw new Error("presence local guard accepted a raw alias, foreign factory, lost returned owner or shared wait");
  const closeBinding = storeFixture.closeFactoryBinding;
  const closeCounts = ["local", "peer"].reduce((counts, lane) => ({ ...counts, [lane]: counts[lane] + 1 }), { local: 0, peer: 0, foreign: 0 });
  if (JSON.stringify(closeCounts) !== JSON.stringify({ local: closeBinding.expectedLocal, peer: closeBinding.expectedPeer, foreign: closeBinding.expectedForeign })) throw new Error("Presence close factory oracle substituted an installed owner");
  const closeSchemaHostiles = [
    { ...storeFixture, closeFactoryBinding: { ...closeBinding, expectedForeign: 2 } },
    { ...storeFixture, closeFactoryBinding: { ...closeBinding, expectedLocal: 0 } },
    { ...storeFixture, closeFactoryBinding: { ...closeBinding, returnReadAfterDetach: false } },
  ];
  for (const hostile of closeSchemaHostiles) if (validateStore(hostile)) throw new Error("Presence close schema admitted foreign or lost returned-read ownership");
  const exactCloseFactories = (source: string): boolean => {
    const start = source.indexOf("pub fn begin_retirement(");
    const open = source.indexOf("{", start);
    const signature = source.slice(start, open);
    const body = start < 0 ? "" : toolJobRustBlock(source, open)?.body ?? "";
    const closeStart = source.indexOf("pub fn close_step(");
    const close = closeStart < 0 ? "" : toolJobRustBlock(source, source.indexOf("{", closeStart))?.body ?? "";
    return !signature.includes("factory:") && body.includes("let Some(local_factory) = self.local_retirement_factory.as_ref() else")
      && body.includes("let local_factory = local_factory.clone();") && body.includes("let peer_factory = self.peer_retirement_factory.clone();")
      && body.includes("!self.peers.is_empty() && self.peer_retirement_factory.is_none()")
      && close.includes("advance_returned_local(reads, &mut self.active_returned, self.local_factory.as_ref()")
      && close.includes('self.local_factory.as_ref().expect("detached local root retains its installed factory").retire(local)')
      && close.includes('self.peer_factory.as_ref().expect("detached nonempty peer root retains its installed factory").clone()');
  };
  if (!exactCloseFactories(retirementSource)) throw new Error("Presence close lost exact original local/peer factory separation");
  const closeSourceHostiles = [
    retirementSource.replace("terminal_is_empty: fn(&P) -> bool,", "terminal_is_empty: fn(&P) -> bool, factory: Arc<dyn SnapshotRetirementFactory<P>>,"),
    retirementSource.replace("let local_factory = local_factory.clone();", "let local_factory = self.peer_retirement_factory.clone().unwrap();"),
    retirementSource.replace("let peer_factory = self.peer_retirement_factory.clone();", "let peer_factory = self.local_retirement_factory.clone();"),
    retirementSource.replace("advance_returned_local(reads, &mut self.active_returned, self.local_factory.as_ref()", "advance_returned_local(reads, &mut self.active_returned, self.peer_factory.as_ref()"),
    retirementSource.replace("!self.peers.is_empty() && self.peer_retirement_factory.is_none()", "false"),
  ];
  for (const hostile of closeSourceHostiles) if (hostile === retirementSource || exactCloseFactories(hostile)) throw new Error("Presence close guard admitted factory substitution or wrong returned-read retirement");
  const closeFactoryChecks = 2 + closeSchemaHostiles.length + closeSourceHostiles.length;
  const commitFixture = JSON.parse(readFileSync(join(storeBase, "🧪️peer-commit.json"), "utf8"));
  const commitSchema = JSON.parse(readFileSync(join(storeBase, "🧬️schema/🔣️peer-commit.schema.json"), "utf8"));
  const validateCommit = new Ajv({ strict: true, allErrors: true }).compile(commitSchema);
  if (!validateCommit(commitFixture)) throw new Error("Presence peer commit fixture violates strict schema");
  for (const law of commitFixture.cases) if (law.accepted !== (law.sameStore && law.sameFactory && !law.stale) || law.expectedSnapshots !== 3 + Number(law.stale)) throw new Error(`Presence peer commit independent identity oracle: ${law.name}`);
  const commitSchemaHostiles = [{ ...commitFixture, maximumBytes: 8192 }, { ...commitFixture, cases: commitFixture.cases.map(law => ({ ...law, accepted: true })) }];
  for (const hostile of commitSchemaHostiles) if (validateCommit(hostile)) throw new Error("Presence peer commit schema admitted forged freshness");
  const exactPeerCommit = toolJobPeerCommitAuthorityExact;
  if (!exactPeerCommit(storeSource, retirementSource)) throw new Error("Presence peer commit lost exact base/factory join or retained alias handoff");
  const commitSourceHostiles = [
    [storeSource.replace("!Arc::ptr_eq(&self.peers, &commit.base_root)", "false"), retirementSource],
    [storeSource.replace("Arc::ptr_eq(factory, &commit.factory)", "true"), retirementSource],
    [storeSource.replace("*retirement.root = Some(previous);\n        drop(commit.base_root);", "drop(commit.base_root);\n        *retirement.root = Some(previous);"), retirementSource],
    [storeSource, retirementSource.replace("base_root: std::mem::ManuallyDrop::new(Some(self.base_root))", "base_root: std::mem::ManuallyDrop::new(None)")],
    [storeSource, retirementSource.replace("if self.base_root.take().is_some()", "if false")],
  ];
  for (const [store, retirement] of commitSourceHostiles) if (exactPeerCommit(store, retirement)) throw new Error("Presence peer commit guard admitted foreign/stale publication or lost base ownership");
  const commitChecks = 2 + commitFixture.cases.length + commitSchemaHostiles.length + commitSourceHostiles.length;
  const peerFixture = JSON.parse(readFileSync(join(storeBase, "🧪️peer-admission.json"), "utf8"));
  const peerSchema = JSON.parse(readFileSync(join(storeBase, "🧬️schema/🔣️peer-admission.schema.json"), "utf8"));
  const validatePeer = new Ajv({ strict: true, allErrors: true }).compile(peerSchema);
  if (!validatePeer(peerFixture)) throw new Error(`peer admission fixture schema: ${JSON.stringify(validatePeer.errors)}`);
  for (const law of peerFixture.cases) {
    const bytes = Buffer.byteLength(law.actor.unit.repeat(law.actor.repeat), "utf8");
    if (bytes !== law.expectedActorBytes || law.accepted !== (law.state === "ready" && bytes > 0 && bytes <= 256) || law.actor.minimumCapacity <= peerFixture.maximumBytes) throw new Error(`peer actor admission independent byte oracle: ${law.name}`);
  }
  if (validatePeer({ ...peerFixture, requiresCapacitySizedByteGrant: true })) throw new Error("peer actor fixture admitted capacity-sized byte credit");
  const rejectionSource = readFileSync(join(storeBase, "🚫️rejection/🦀️.rs"), "utf8");
  const pluginSource = readFileSync(join(storeBase, "../../🔌️plugin/🦀️.rs"), "utf8");
  const exactRejectedActor = (store: string, rejection: string, plugin: string): boolean => {
    const start = store.indexOf("pub fn adopt(&mut self, actor: String, presence: P");
    const adopt = start < 0 ? "" : toolJobRustBlock(store, store.indexOf("{", start))?.body ?? "";
    return (adopt.match(/return Err\(PresencePeerAdmissionRejected::new\("[^"\n]+", actor, presence, self\.factory\.clone\(\)\)\)/g) ?? []).length === 5
      && !store.includes("pub fn retire_rejected(")
      && rejection.includes("pub fn into_retirement(mut self) -> Box<dyn ErasedSnapshotRetirement>")
      && rejection.includes("self.factory.take().expect(\"rejected admission retains its minting publication factory\")")
      && rejection.includes("actor: std::mem::ManuallyDrop<String>")
      && rejection.includes("Some(actor.into_bytes())")
      && rejection.includes("let released_bytes = actor.len().min(maximum_bytes)")
      && rejection.includes("actor.truncate(actor.len() - released_bytes)")
      && rejection.includes("drop(self.actor.take())")
      && !rejection.includes("capacity() > maximum_bytes")
      && plugin.includes("Some(rejected.into_retirement())");
  };
  if (!exactRejectedActor(storeSource, rejectionSource, pluginSource)) throw new Error("peer rejection lost its exact actor/presence owner or byte cursor");
  const rejectedHostiles = [
    [storeSource.replace('"presence peer actor is empty or exceeds its fixed byte authority", actor, presence', '"presence peer actor is empty or exceeds its fixed byte authority", String::new(), presence'), rejectionSource, pluginSource],
    [storeSource, rejectionSource.replace("actor.len().min(maximum_bytes)", "actor.capacity()"), pluginSource],
    [storeSource, rejectionSource.replace("drop(self.actor.take())", "return Err(\"capacity() > maximum_bytes\".into())"), pluginSource],
    [storeSource, rejectionSource, pluginSource.replace("Some(rejected.into_retirement())", "None")],
    [storeSource.replaceAll("actor, presence, self.factory.clone()", "actor, presence, foreign_factory.clone()"), rejectionSource, pluginSource],
    [storeSource, rejectionSource.replace('self.factory.take().expect("rejected admission retains its minting publication factory")', "foreign_factory"), pluginSource],
  ];
  for (const [store, rejection, plugin] of rejectedHostiles) if (exactRejectedActor(store, rejection, plugin)) throw new Error("peer rejection guard accepted dropped identity, false byte credit or missing mounted owner");
  if (validatePeer({ ...peerFixture, factoryBinding: { ...peerFixture.factoryBinding, expectedForeignRetirements: 1 } })) throw new Error("peer rejection fixture accepted a foreign factory");
  const channelSource = readFileSync(join(storeBase, "../../📡️spr/🧵️channel/🦀️.rs"), "utf8");
  const captureProof = (plugin: string, store: string, channel: string, retirement: string): boolean => toolJobPeerInteractionRootsExact(plugin, store, channel, retirement);
  if (!captureProof(pluginSource, storeSource, channelSource, retirementSource)) throw new Error("peer capture census rejected its real exact helper/base/factory authority");
  const captureHostiles = [
    [pluginSource.replace("self.start_typed_command_operation(command, admission, meta, operation_id, None).await", "self.foreign_command_operation(command, admission, meta, operation_id, None).await"), storeSource, channelSource, retirementSource],
    [pluginSource.replace("let presence_peers = self.presence_store.peers_root();", "let presence_peers = self.presence_store.peers().await;"), storeSource, channelSource, retirementSource],
    [pluginSource, storeSource.replace("!Arc::ptr_eq(&self.peers, &commit.base_root)", "false"), channelSource, retirementSource],
    [pluginSource, storeSource.replace("Arc::ptr_eq(factory, &commit.factory)", "true"), channelSource, retirementSource],
    [pluginSource, storeSource.replace("base_root: Arc<PresencePeersRoot<P>>,", "pub base_root: Arc<PresencePeersRoot<P>>,"), channelSource, retirementSource],
    [pluginSource, storeSource.replace("pub struct PresencePeersCommit<P> {", "pub struct PresencePeersCommit<P> { pub factory_override: Arc<dyn SnapshotRetirementFactory<P>>,"), channelSource, retirementSource],
    [pluginSource, storeSource.replace("*retirement.root = Some(previous);\n        drop(commit.base_root);", "drop(commit.base_root);\n        *retirement.root = Some(previous);"), channelSource, retirementSource],
    [pluginSource, storeSource, channelSource, retirementSource.replace("base_root: std::mem::ManuallyDrop::new(Some(self.base_root))", "base_root: std::mem::ManuallyDrop::new(None)")],
    [pluginSource.replace("self.validate_peer_roster_publication(seq, generation, &cancel)", "self.accept_unchecked_roster(seq, generation, &cancel)"), storeSource, channelSource, retirementSource],
    [pluginSource, storeSource, channelSource.replace("pub fn admit_page(seq: u64, own_color: Option<u8>, item_count: u32, page: FixedCommandPage)", "pub fn decode_before_admission(seq: u64, own_color: Option<u8>, item_count: u32, page: FixedCommandPage)"), retirementSource],
  ];
  for (const [plugin, store, channel, retirement] of captureHostiles) {
    if (plugin === pluginSource && store === storeSource && channel === channelSource && retirement === retirementSource) throw new Error("peer capture hostile missed its exact source target");
    if (captureProof(plugin, store, channel, retirement)) throw new Error("peer capture census admitted a forged helper, public authority, stale root, foreign factory or bypassed ingress");
  }
  return 1 + fixture.cases.length + fixture.storeCases.length + 2 + 1 + storeFixture.cases.length + 30 + peerFixture.cases.length + closeFactoryChecks + commitChecks + 1 + captureHostiles.length;
}

/** 🧪️ Cross-checks full-domain scope fixtures with Ajv equality and guards the active retained admission/publication seam. */
export function toolJobLatestWinsSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️tool-latest-wins.json"), "utf8"));
  const schema = JSON.parse(readFileSync(join(base, "🧪️tool-latest-wins.schema.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const ajv = new Ajv({ strict: true, allErrors: true });
  const validate = ajv.compile(schema);
  if (!validate(fixture)) throw new Error(`latest-wins schema: ${JSON.stringify(validate.errors)}`);
  const equal = ajv.compile({ const: fixture.first });
  for (const law of fixture.cases) {
    if (Buffer.byteLength(law.next.target, "utf8") !== fixture.targetBytes || equal(law.next) !== law.superseded) throw new Error(`latest-wins exact scope oracle: ${law.id}`);
  }
  const hostiles = [
    { ...fixture, maximumItems: 2 },
    { ...fixture, maximumBytes: 8_192 },
    { ...fixture, first: { ...fixture.first, document: undefined } },
    { ...fixture, first: { ...fixture.first, inventedAuthority: true } },
  ];
  for (const hostile of hostiles) if (validate(hostile)) throw new Error("latest-wins schema accepted a forged scope or enlarged grant");
  const integration = JSON.parse(readFileSync(join(base, "🧪️tool-latest-wins-integration.json"), "utf8"));
  const integrationSchema = JSON.parse(readFileSync(join(base, "🧪️tool-latest-wins-integration.schema.json"), "utf8"));
  const validateIntegration = ajv.compile(integrationSchema);
  if (!validateIntegration(integration)) throw new Error(`latest-wins integration schema: ${JSON.stringify(validateIntegration.errors)}`);
  for (const law of integration.cases) {
    const same = ajv.compile({ const: law.firstTarget });
    if (same(law.nextTarget) !== law.firstCancelled) throw new Error(`latest-wins integration equality oracle: ${law.id}`);
  }
  if (Buffer.byteLength(integration.keyRetirement.text, "utf8") !== integration.keyRetirement.utf8Bytes
    || JSON.stringify(Array.from(integration.keyRetirement.text as string).reverse().map((scalar) => Buffer.byteLength(scalar, "utf8"))) !== JSON.stringify(integration.keyRetirement.scalarBytes)) throw new Error("latest-wins UTF-8 retirement byte oracle");
  const integrationHostiles = [
    { ...integration, maximumItems: 64 },
    { ...integration, rebase: { ...integration.rebase, cancelOldKey: true } },
    { ...integration, slotReservation: { ...integration.slotReservation, collisionAdmitted: true } },
    { ...integration, reclamation: { ...integration.reclamation, acceptedTargets: 64 } },
    { ...integration, fairness: { ...integration.fairness, secondPublishesWithinMetadataVisits: 65 } },
    { ...integration, keyRetirement: { ...integration.keyRetirement, utf8Bytes: 3 } },
    { ...integration, lostReservations: integration.lostReservations.map((law: object) => ({ ...law, rejectionAfterVacancy: false })) },
  ];
  for (const hostile of integrationHostiles) if (validateIntegration(hostile)) throw new Error("latest-wins integration schema accepted stale authority, collision, starvation, or a missing accepted target");
  const source = readFileSync(join(base, "🦀️.rs"), "utf8");
  const body = (text: string, name: string): string => {
    const start = text.lastIndexOf(`fn ${name}(`);
    return start < 0 ? "" : toolJobRustBlock(text, text.indexOf("{", start))?.body ?? "";
  };
  const obligations: Array<[string, string]> = [
    ["publish_mounted_typed_operation_unit", "mounted.reject_cancelled_publication()?"],
    ["publish_mounted_typed_operation_unit", "ToolCancellationLease::try_claim_publication"],
    ["reject_cancelled_publication", "pending.begin_close()"],
    ["reject_cancelled_publication", "self.publication = completion.take()?"],
    ["advance_latest_wins_command_one", "self.latest_wins_order.items.front().copied()"],
    ["advance_latest_wins_command_one", "self.start_typed_command_operation(command, admission"],
    ["advance_latest_wins_admission_unit", "pending.restarting = true"],
    ["advance_latest_wins_admission_unit", "self.latest_wins_keys.begin(operation, key.clone()"],
    ["advance_latest_wins_admission_unit", "registration.latest_wins_target"],
    ["dispatch_typed_command_inner", "registration.latest_wins_command_disposer"],
    ["dispatch_typed_command_inner", "self.tool_cancellations.begin_keyed"],
    ["dispatch_typed_command_inner", "self.latest_wins_order.push(operation_id.0)"],
    ["dispatch_typed_command_inner", "self.can_admit_typed_operation(operation_id.0)"],
    ["advance_latest_wins_admission_unit", ".rebind_keyed(base_revision, generation)?"],
    ["rebind_keyed", "scope.operation != self.key"],
    ["rebind_keyed", "scope.operation.generation = generation"],
    ["advance_typed_operation_publication_one", "next_id_from(self.typed_publication_cursor)"],
    ["take_typed_operation_result_page", "next_id_from(self.typed_result_cursor)"],
    ["cleanup_finished_slot", "scope.publication_claim.is_finished()"],
    ["release_current", "std::sync::Arc::ptr_eq(&scope.publication_claim, &self.publication_claim)"],
    ["try_claim_publication", "self.handle.publication_scope.try_claim()?"],
    ["try_claim_publication", "self.publication_claim.try_claim()?"],
  ];
  const exact = (text: string): boolean => obligations.every(([name, token]) => body(text, name).includes(token))
    && !body(text, "publish_mounted_typed_operation_unit").includes(".await")
    && !body(text, "publish_mounted_typed_operation_unit").includes("dispatch_emit_group(")
    && text.includes("self.token.child_now()")
    && text.includes("compare_exchange(0, 1, std::sync::atomic::Ordering::AcqRel")
    && text.includes("scope.operation")
    && text.includes("retained_latest_wins_real_document_publication_cancellation_and_exhausted_ack_close");
  if (!exact(source)) throw new Error("latest-wins production admission/publication authority is incomplete");
  for (const [, token] of obligations) if (exact(source.replaceAll(token, "unqualified_authority"))) throw new Error(`latest-wins accepts missing authority: ${token}`);
  const rawFixture = JSON.parse(readFileSync(join(base, "🧵️retained-command/🧪️fixtures/🔣️raw-allocation-close.json"), "utf8"));
  const rawSchema = JSON.parse(readFileSync(join(base, "🧵️retained-command/🧬️schema/🔣️raw-allocation-close.schema.json"), "utf8"));
  const validateRaw = ajv.compile(rawSchema);
  if (!validateRaw(rawFixture)) throw new Error(`retained raw allocation schema: ${JSON.stringify(validateRaw.errors)}`);
  for (const law of rawFixture.cases) {
    const oracle = Buffer.alloc(law.capacity).subarray(0, law.initializedBytes);
    if (oracle.byteLength !== law.expectedByteRelease || law.capacity <= rawFixture.maximumBytes) throw new Error(`retained raw allocation initialized-byte oracle: ${law.id}`);
  }
  const rawSource = readFileSync(join(base, "🧵️retained-command/🦀️.rs"), "utf8");
  const rawClose = (text: string): boolean => text.includes("if self.raw.capacity() != 0 {\n            if maximum_items == 0 {")
    && !text.includes("maximum_bytes < self.raw.capacity()") && !text.includes("let released = self.raw.capacity()")
    && text.includes("fn test_raw_allocation_close<A: ArtifactApp>()");
  if (!rawClose(rawSource)) throw new Error("retained command raw capacity incorrectly consumes semantic byte credit");
  if (rawClose(rawSource.replace("if self.raw.capacity() != 0 {\n            if maximum_items == 0 {", "if self.raw.capacity() != 0 {\n            if maximum_items == 0 || maximum_bytes < self.raw.capacity() {"))) throw new Error("retained raw close accepts capacity-sized byte deadlock");
  const storeSource = readFileSync(join(base, "../🏪️store/🦀️.rs"), "utf8");
  const publisherStart = source.lastIndexOf("fn publish_mounted_typed_operation_unit(");
  const mutatePublisher = (before: string, after: string): string => source.slice(0, publisherStart) + source.slice(publisherStart).replace(before, after);
  const mountedChecks: Array<[string, (text: string) => boolean, string]> = [
    ["synchronous move-only unit", (text) => { const publisher = body(text, "publish_mounted_typed_operation_unit"); return text.includes("fn publish_mounted_typed_operation_unit") && !text.includes("async fn publish_mounted_typed_operation_unit") && ["artifact_mutations", "config_mutations", "draft_mutations", "presence", "transient"].every((lane) => publisher.includes(`${lane}.pop()`)) && !publisher.includes(".last().cloned()") && !publisher.includes(".await"); }, mutatePublisher("fn publish_mounted_typed_operation_unit", "async fn publish_mounted_typed_operation_unit")],
    ["synchronous fresh publisher", toolJobPublicationFreshnessBeforeEveryTurn, source.replace("typed_operation_document_is_fresh(&mounted.operation", "accept_stale_operation(&mounted.operation")],
    ["exact extracted setup", (text) => !!toolJobRetainedDispatchSetup(text), source.replace("self.start_typed_command_operation(command, admission, meta, operation_id, None).await", "self.unchecked_command_operation(command, admission, meta, operation_id, None).await")],
    ["unsupported generic reducer denial", toolJobTypedRouteFailsClosedBeforePreparation, source.replace("QualifiedToolProof::FrameworkOwned(_) | QualifiedToolProof::Bounded(_) => {", "QualifiedToolProof::FrameworkOwned(_) | QualifiedToolProof::Bounded(_) => { return Ok(());")],
    ["mounted persistent operation", toolJobTypedPersistentFoundation, source.replace("session.pump_one(pool, semio_framework_async::Lane::Interactive)", "session.run_to_terminal(pool)")],
    ["retained ephemeral publisher", (text) => toolJobEphemeralOneItemPublicationBounded(storeSource, text), source.replace("self.presence_one_item_factory.as_deref()", "A::build_presence_store_one_item_preparation_factory()")],
  ];
  mountedChecks.push(["move-only mutation ownership", mountedChecks[0][1], mutatePublisher("emit.artifact_mutations.pop()", "emit.artifact_mutations.last().cloned()")]);
  for (const [name, check, hostile] of mountedChecks) {
    if (!check(source)) throw new Error(`mounted source binding rejected its real ${name}`);
    if (hostile === source || check(hostile)) throw new Error(`mounted source binding accepted hostile ${name}`);
  }
  if (!toolJobStoreOneItemPublicationBounded(storeSource, source)) throw new Error("mounted Store source binding lost its retained owned-preparation helper");
  const replayingOwnedBegin = storeSource.replace("let base = match self.snapshot_read() {", "replay_mutations(); let base = match self.snapshot_read() {");
  if (replayingOwnedBegin === storeSource || toolJobStoreOneItemPublicationBounded(replayingOwnedBegin, source)) throw new Error("mounted Store source binding accepted replay inside extracted preparation");
  const dispatchFixture = JSON.parse(readFileSync(join(base, "🧵️retained-command/🧪️fixtures/🔣️mounted-dispatch-binding.json"), "utf8"));
  const dispatchSchema = JSON.parse(readFileSync(join(base, "🧵️retained-command/🧬️schema/🔣️mounted-dispatch-binding.schema.json"), "utf8"));
  const validateDispatch = ajv.compile(dispatchSchema);
  if (!validateDispatch(dispatchFixture)) throw new Error(`mounted dispatch fixture: ${JSON.stringify(validateDispatch.errors)}`);
  const validDispatch = ajv.compile({ const: "none" });
  const production = toolJobProductionSource(source);
  const mutateFunction = (text: string, name: string, before: string, after: string): string => {
    const start = text.lastIndexOf(`async fn ${name}(`);
    const block = start < 0 ? undefined : toolJobRustBlock(text, text.indexOf("{", start));
    if (!block) throw new Error(`mounted dispatch hostile target missing: ${name}`);
    return text.slice(0, start) + text.slice(start, block.end).replace(before, after) + text.slice(block.end);
  };
  const mutations: Record<string, (text: string) => string> = {
    none: (text) => text,
    "wrong-helper": (text) => text.replace("self.start_typed_command_operation(command, admission, meta, operation_id, None).await", "self.other_command_operation(command, admission, meta, operation_id, None).await"),
    "missing-helper": (text) => text.replace("async fn start_typed_command_operation(", "async fn unrelated_command_operation("),
    "duplicate-helper": (text) => `${text}\nasync fn start_typed_command_operation() {}`,
    "missing-pipeline-guard": (text) => mutateFunction(text, dispatchFixture.dispatcher, "self.require_complete_tool_operation_pipeline(&admission)?", "self.accept_incomplete_pipeline(&admission)?"),
    "duplicate-session": (text) => mutateFunction(text, dispatchFixture.helper, "let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new", "semio_framework_job::MountedWorkerJobSession::try_new(extra, params); let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new"),
    "duplicate-pump": (text) => mutateFunction(text, dispatchFixture.helper, "let _ = active.drive_worker_step(&pool)?", "let _ = active.drive_worker_step(&pool)?; let _ = active.drive_worker_step(&pool)?"),
    "direct-reducer": (text) => mutateFunction(text, dispatchFixture.dispatcher, "self.require_complete_tool_operation_pipeline(&admission)?", "A::handle(&command).await; self.require_complete_tool_operation_pipeline(&admission)?"),
    "direct-dispatch": (text) => mutateFunction(text, dispatchFixture.dispatcher, "self.require_complete_tool_operation_pipeline(&admission)?", "self.tool_jobs.dispatch(operation_spec); self.require_complete_tool_operation_pipeline(&admission)?"),
    "run-to-completion": (text) => mutateFunction(text, dispatchFixture.helper, "let _ = active.drive_worker_step(&pool)?", "let _ = active.run_to_completion(&pool)?; let _ = active.drive_worker_step(&pool)?"),
  };
  if (new Set(dispatchFixture.cases.map((law: { mutation: string }) => law.mutation)).size !== Object.keys(mutations).length) throw new Error("mounted dispatch fixture omits an exact hostile case");
  for (const law of dispatchFixture.cases) {
    const changed = mutations[law.mutation]!(production);
    if (validDispatch(law.mutation) !== law.admitted || (law.mutation !== "none" && changed === production)) throw new Error(`mounted dispatch fixture oracle: ${law.mutation}`);
    if (toolJobMountedDispatchOneTurnExact(changed) !== law.admitted) throw new Error(`mounted dispatch exact helper law: ${law.mutation}`);
  }
  return fixture.cases.length + hostiles.length + obligations.length + integration.cases.length + integrationHostiles.length + rawFixture.cases.length + 4 + mountedChecks.length * 2 + 2 + dispatchFixture.cases.length * 2;
}
//#endregion 🗝️LatestWinsAuthorityLaws

//#region 🔏️CanonicalEditSealerLaws
/** 🧪️ Validates language-neutral canonical bytes and private Store sealer source boundaries. */
export function storeCanonicalEditSealerSelfTests(): { grants: number; schemaHostiles: number; sourceHostiles: number; digestOracles: number; mapGrants: number; mapSchemaHostiles: number; mapSourceHostiles: number; mapDigestOracles: number; readerChecks: number } {
  const storePath = "🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store";
  const base = join(WORKSPACE_ROOT, storePath, "🧵️canonical-edit");
  const schema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️canonical-edit-sealer.schema.json"), "utf8"));
  const fixture = JSON.parse(readFileSync(join(base, "🧪️fixtures/🔣️canonical-edit-sealer.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  if (!validate(fixture)) throw new Error(`canonical edit fixture schema: ${JSON.stringify(validate.errors)}`);
  const schemaHostiles = [
    { ...fixture, extra: true },
    { ...fixture, edit: { ...fixture.edit, extra: true } },
    { ...fixture, edit: { ...fixture.edit, forwards: [{ Unknown: {} }] } },
    { ...fixture, edit: { ...fixture.edit, forwards: [{ Replace: { ...fixture.edit.forwards[0].Replace, text: 1 } }] } },
    { ...fixture, edit: { ...fixture.edit, mutationMeta: [{ ...fixture.edit.mutationMeta[0], timestamp: { actor: 1, physical_ms: 42, logical: 2, extra: true } }] } },
    { ...fixture, edit: { ...fixture.edit, mutationMeta: [{ ...fixture.edit.mutationMeta[0], undo_policy: "Unknown" }] } },
    { ...fixture, grants: [0, -1, 2, 7, 256, 4096] },
    { ...fixture, expectedDigest: "forged" },
    { ...fixture, hostile: [...fixture.hostile, "forged-arbitrary-authority"] },
  ];
  for (const hostile of schemaHostiles) if (validate(hostile)) throw new Error("strict canonical sealer schema accepted hostile input");
  const utf8 = new TextEncoder();
  function* canonicalBytes(value: unknown): Generator<number> {
    if (typeof value === "string") {
      yield 34;
      for (const character of value) {
        const scalar = character.codePointAt(0)!;
        const escaped = character === '"' ? '\\"' : character === "\\" ? "\\\\" : scalar === 8 ? "\\b" : scalar === 9 ? "\\t" : scalar === 10 ? "\\n" : scalar === 12 ? "\\f" : scalar === 13 ? "\\r" : scalar < 32 ? `\\u${scalar.toString(16).padStart(4, "0")}` : character;
        yield* utf8.encode(escaped);
      }
      yield 34;
    } else if (Array.isArray(value)) {
      yield 91;
      for (let index = 0; index < value.length; index++) { if (index) yield 44; yield* canonicalBytes(value[index]); }
      yield 93;
    } else if (value !== null && typeof value === "object") {
      yield 123;
      let index = 0;
      for (const key of Object.keys(value)) { if (index++) yield 44; yield* canonicalBytes(key); yield 58; yield* canonicalBytes((value as Record<string, unknown>)[key]); }
      yield 125;
    } else {
      yield* utf8.encode(JSON.stringify(value));
    }
  }
  const expected = utf8.encode(fixture.expectedJson);
  if (fixture.expectedJson !== JSON.stringify(fixture.edit) || expected.length <= 4096) throw new Error("canonical edit JSON oracle mismatch");
  for (const maximum of fixture.grants.filter((value: number) => value > 0)) {
    const iterator = canonicalBytes(fixture.edit);
    const actual: number[] = [];
    let complete = false;
    while (!complete) {
      const before = actual.length;
      for (let count = 0; count < Math.min(maximum, 256); count++) {
        const step = iterator.next();
        if (step.done) { complete = true; break; }
        actual.push(step.value);
      }
      if (actual.length - before > maximum) throw new Error("canonical edit byte grant exceeded");
    }
    if (!Buffer.from(actual).equals(expected)) throw new Error(`canonical edit byte oracle mismatch for grant ${maximum}`);
  }
  const hash = createHash("sha256");
  const integer = (value: number) => { const bytes = Buffer.alloc(8); bytes.writeBigUInt64BE(BigInt(value)); return bytes; };
  hash.update("semio.artifact.cursor.v2");
  for (const part of [utf8.encode("edit"), utf8.encode(fixture.edit.id), expected]) { hash.update(integer(part.length)); hash.update(part); }
  if (hash.digest("hex") !== fixture.expectedDigest) throw new Error("canonical edit third-party digest oracle mismatch");
  const store = readFileSync(join(WORKSPACE_ROOT, storePath, "🦀️.rs"), "utf8");
  const source = readFileSync(join(base, "🦀️.rs"), "utf8");
  const method = (text: string, pattern: RegExp) => { const start = text.search(pattern); return start < 0 ? "" : toolJobRustBlock(text, text.indexOf("{", start))?.body ?? ""; };
  const exact = (storeText: string, sealerText: string) => {
    const validation = method(storeText, /fn validate_prepared</);
    const mint = method(storeText, /fn seal_prepared_owned</);
    const advance = method(sealerText, /pub fn advance\(&mut self, grant: ArtifactStoreOneItemGrant/);
    const commitStart = storeText.indexOf("ArtifactStoreOneItemPublicationPhase::PreflightingCommit =>", storeText.indexOf("pub fn advance_apply_one("));
    const commit = commitStart < 0 ? "" : toolJobRustBlock(storeText, storeText.indexOf("{", commitStart))?.body ?? "";
    return validation.includes("Arc::ptr_eq(self, &prepared.seal.authority)")
      && validation.includes("prepared.seal.edit_address != prepared.edit.as_ref() as *const")
      && validation.includes("prepared.seal.post_address != Arc::as_ptr(&prepared.post_snapshot)")
      && validation.includes("prepared.seal.digest != prepared.edit_digest")
      && mint.includes("edit_address: edit.as_ref() as *const") && mint.includes("digest: edit_digest")
      && !/pub\s+fn\s+seal_prepared/.test(storeText)
      && advance.includes("self.encoder.encode_chunk(edit.as_ref(), &mut self.last_chunk[..maximum])")
      && advance.includes("self.hash.update(&self.last_chunk[..self.last_length])")
      && advance.includes("authority.seal_prepared_owned(edit, post, self.hash.clone().finalize(), identities)")
      && !/serde_json::to_(?:vec|value|string)|prepared_edit_digest\(/.test(advance)
      && commit.includes("authority.validate_prepared(prepared)") && !commit.includes("prepared_edit_digest(");
  };
  if (!exact(store, source)) throw new Error("live Store canonical sealer authority/byte source linkage missing");
  const sourceHostiles = [
    [store.replace("Arc::ptr_eq(self, &prepared.seal.authority)", "true"), source],
    [store.replace("prepared.seal.edit_address != prepared.edit.as_ref() as *const", "prepared.seal.edit_address != forged_edit as *const"), source],
    [store.replace("prepared.seal.post_address != Arc::as_ptr(&prepared.post_snapshot)", "prepared.seal.post_address != 0"), source],
    [store.replace("authority.validate_prepared(prepared)", "authority.prepared_edit_digest(&prepared.edit)"), source],
    [store.replace("fn seal_prepared_owned<", "pub fn seal_prepared_owned<"), source],
    [store, source.replace("self.encoder.encode_chunk(edit.as_ref(), &mut self.last_chunk[..maximum])", "serde_json::to_vec(edit.as_ref())")],
  ];
  for (const [candidateStore, candidateSealer] of sourceHostiles) if (exact(candidateStore, candidateSealer)) throw new Error("canonical Store sealer accepted hostile authority/serialization source");
  const mapSchema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️canonical-borrowed-map.schema.json"), "utf8"));
  const mapFixture = JSON.parse(readFileSync(join(base, "🧪️fixtures/🔣️canonical-borrowed-map.json"), "utf8"));
  const validateMap = new Ajv({ strict: true, allErrors: true }).compile(mapSchema);
  if (!validateMap(mapFixture)) throw new Error(`borrowed map fixture schema: ${JSON.stringify(validateMap.errors)}`);
  const mapSchemaHostiles = [{ ...mapFixture, extra: true }, { ...mapFixture, longKeyBytes: 4096 }, { ...mapFixture, lifetime: { ...mapFixture.lifetime, iteratorDropsBeforeRoot: false } }, { ...mapFixture, hostile: ["unchecked-pointer"] }];
  for (const hostile of mapSchemaHostiles) if (validateMap(hostile)) throw new Error("borrowed map schema accepted hostile lifetime shape");
  const mapExpected = utf8.encode(mapFixture.expectedJson);
  if (mapFixture.expectedJson !== JSON.stringify(mapFixture.edit)) throw new Error("borrowed map canonical JSON oracle mismatch");
  const keys = Object.keys(mapFixture.edit.forwards[0].ReplaceMap.map);
  if (Math.max(...keys.map((key) => utf8.encode(key).length)) !== mapFixture.longKeyBytes) throw new Error("borrowed map long key is not the advertised UTF-8 length");
  for (const grant of mapFixture.grants.filter((value: number) => value > 0)) {
    const stream = canonicalBytes(mapFixture.edit);
    const actual: number[] = [];
    let done = false;
    while (!done) for (let count = 0; count < Math.min(grant, 256); count++) {
      const next = stream.next();
      if (next.done) { done = true; break; }
      actual.push(next.value);
    }
    if (!Buffer.from(actual).equals(mapExpected)) throw new Error("borrowed map byte oracle mismatch");
  }
  const mapHash = createHash("sha256");
  mapHash.update("semio.artifact.cursor.v2");
  for (const part of [utf8.encode("edit"), utf8.encode(mapFixture.edit.id), mapExpected]) { mapHash.update(integer(part.length)); mapHash.update(part); }
  if (mapHash.digest("hex") !== mapFixture.expectedDigest) throw new Error("borrowed map Node crypto digest oracle mismatch");
  const borrowed = readFileSync(join(base, "🧵️borrowed/🦀️.rs"), "utf8");
  const borrowedExact = (parent: string, child: string) => {
    const close = method(parent, /pub fn close_step\(&mut self, grant: ArtifactStoreOneItemGrant/);
    const bind = method(child, /fn bind</);
    return parent.includes("pub trait ArtifactCanonicalJson: Sync")
      && parent.indexOf("encoder: ArtifactCanonicalEditEncoder") < parent.indexOf("edit: Option<Box<Edit<M>>>")
      && close.indexOf("self.encoder.close_step()") >= 0 && close.indexOf("self.encoder.close_step()") < close.indexOf("self.edit.take()")
      && bind.includes("self.root_address != address") && bind.includes("root.canonical_json_borrowed_root()")
      && child.includes("pub(super) struct ArtifactCanonicalEditEncoder")
      && child.includes("Iterator<Item = (&'a str, ArtifactCanonicalJsonValue<'a>)> + Send + 'a")
      && child.includes("values.values.next()") && child.includes("self.frames[self.depth] = None")
      && parent.includes("self.depth >= self.maximum_depth") && child.includes("maximum_depth: ARTIFACT_CANONICAL_JSON_DEPTH - top")
      && !/\.nth\(|\.range\(|serde_json::to_(?:vec|value|string)/.test(child);
  };
  if (!borrowedExact(source, borrowed)) throw new Error("borrowed map private root lifetime/source linkage missing");
  const mapSourceHostiles = [
    [source.replace("pub trait ArtifactCanonicalJson: Sync", "pub trait ArtifactCanonicalJson"), borrowed],
    [source.replace("self.encoder.close_step()", "self.edit.take()"), borrowed],
    [source, borrowed.replace("self.root_address != address", "false")],
    [source, borrowed.replace("values.values.next()", "values.values.nth(0)")],
    [source, borrowed.replace("pub(super) struct ArtifactCanonicalEditEncoder", "pub struct ArtifactCanonicalEditEncoder")],
    [source, borrowed.replace("maximum_depth: ARTIFACT_CANONICAL_JSON_DEPTH - top", "maximum_depth: ARTIFACT_CANONICAL_JSON_DEPTH")],
  ];
  for (const [parent, child] of mapSourceHostiles) if (borrowedExact(parent, child)) throw new Error("borrowed map accepted hostile lifetime/source substitution");
  const readerSchema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️canonical-reader.schema.json"), "utf8"));
  const readerFixture = JSON.parse(readFileSync(join(base, "🧪️fixtures/🔣️canonical-reader.json"), "utf8"));
  const readerValidate = new Ajv({ strict: true, allErrors: true }).compile(readerSchema);
  if (!readerValidate(readerFixture) || readerFixture.expectedByteLength !== mapExpected.length || createHash("sha256").update(mapExpected).digest("hex") !== readerFixture.expectedJsonSha256) throw new Error("typed canonical reader schema/Node byte oracle mismatch");
  const readerSchemaHostiles = [{ ...readerFixture, extra: true }, { ...readerFixture, sourceFixture: "unbound-root" }, { ...readerFixture, grants: [0, 1, 7, 4097] }];
  for (const hostile of readerSchemaHostiles) if (readerValidate(hostile)) throw new Error("strict canonical reader schema accepted hostile input");
  for (const maximum of readerFixture.grants.filter((grant: number) => grant > 0)) {
    const iterator = canonicalBytes(mapFixture.edit);
    const actual: number[] = [];
    let done = false;
    while (!done) for (let index = 0; index < Math.min(maximum, 256); index += 1) { const next = iterator.next(); if (next.done) { done = true; break; } actual.push(next.value); }
    if (!Buffer.from(actual).equals(mapExpected)) throw new Error("canonical reader bounded byte oracle mismatch");
  }
  const reader = readFileSync(join(base, "📖️reader/🦀️.rs"), "utf8");
  const readerExact = (text: string) => {
    const close = method(text, /fn close_step\(&mut self, grant: ArtifactStoreOneItemGrant/);
    const transfer = method(text, /fn take_root\(&mut self\)/);
    const encode = method(text, /fn encode_chunk\(&mut self, grant: ArtifactStoreOneItemGrant/);
    return text.indexOf("encoder: ArtifactCanonicalEditEncoder") < text.indexOf("root: Option<Arc<T>>")
      && close.indexOf("self.encoder.close_step()") >= 0 && close.indexOf("self.encoder.close_step()") < close.indexOf("self.root.take()")
      && transfer.includes("if self.closing { self.encoder.terminal_is_empty() } else { self.is_complete() }") && transfer.includes("self.encoder.reset()")
      && text.includes("owned: ManuallyDrop<ReaderState<T>>") && text.includes("!self.cancelled && !self.failed && !self.closing && self.encoder.is_complete()")
      && text.includes("!std::thread::panicking()") && text.includes("ManuallyDrop::drop(&mut self.owned)")
      && encode.includes("self.encoder.encode_chunk(root.as_ref(), &mut output[..maximum])") && encode.includes("grant.maximum_bytes.min(output.len()).min(ARTIFACT_CANONICAL_JSON_CHUNK_BYTES)")
      && !/seal_prepared|serde_json::to_(?:vec|value|string)|unsafe impl/.test(text);
  };
  if (!readerExact(reader)) throw new Error("canonical reader exact retained root wiring missing");
  const readerSourceHostiles = [
    reader.replace("self.encoder.close_step()", "self.root.take()"),
    reader.replace("if self.closing { self.encoder.terminal_is_empty() } else { self.is_complete() }", "self.encoder.is_complete() || self.closing && self.encoder.terminal_is_empty()"),
    reader.replace("self.encoder.encode_chunk(root.as_ref(), &mut output[..maximum])", "serde_json::to_vec(root)"),
    reader.replace("grant.maximum_bytes.min(output.len()).min(ARTIFACT_CANONICAL_JSON_CHUNK_BYTES)", "output.len()"),
    reader.replace("owned: ManuallyDrop<ReaderState<T>>", "owned: ReaderState<T>"),
    reader.replace("!std::thread::panicking()", "true"),
  ];
  for (const hostile of readerSourceHostiles) if (readerExact(hostile)) throw new Error("canonical reader accepted hostile ownership/grant substitution");
  return { grants: fixture.grants.length - 1, schemaHostiles: schemaHostiles.length, sourceHostiles: sourceHostiles.length, digestOracles: 1, mapGrants: mapFixture.grants.length - 1, mapSchemaHostiles: mapSchemaHostiles.length, mapSourceHostiles: mapSourceHostiles.length, mapDigestOracles: 1, readerChecks: 1 + readerSchemaHostiles.length + readerFixture.grants.length - 1 + readerSourceHostiles.length + canonicalErrorProgressSelfTests() };
}

export function canonicalErrorProgressSelfTests(): number {
  const base = join(WORKSPACE_ROOT, "🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🧵️canonical-edit");
  const fixture = JSON.parse(readFileSync(join(base, "🧪️fixtures/🔣️canonical-error-progress.json"), "utf8"));
  const schema = JSON.parse(readFileSync(join(base, "🧬️schema/🔣️canonical-error-progress.schema.json"), "utf8"));
  const Ajv = createRequire(import.meta.url)("ajv");
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  if (!validate(fixture)) throw new Error("canonical error-progress fixture violates strict schema");
  const prefix = Buffer.from(JSON.stringify([fixture.text, null]).slice(0, -5));
  if (!prefix.equals(Buffer.from(fixture.expectedPrefix)) || prefix.length !== fixture.expectedBytes || Buffer.byteLength(fixture.text) !== fixture.expectedSnapshotBytes) throw new Error("canonical error-progress independent JSON/UTF-8 oracle mismatch");
  const hostiles = [{ ...fixture, extra: true }, { ...fixture, expectedBytes: 7 }, { ...fixture, expectedComplete: true }, { ...fixture, grants: [4097] }, { ...fixture, expectedRootRetirements: 0 }];
  for (const hostile of hostiles) if (validate(hostile)) throw new Error("canonical error-progress schema admitted forged credit or completion");
  let checks = 1 + hostiles.length;
  for (const mode of fixture.modes) for (const maximum of fixture.grants) {
    const grant = Math.min(maximum, 256);
    let written = 0;
    if (grant > 0) while (written < prefix.length) { const count = Math.min(grant, prefix.length - written); const output = Buffer.alloc(512, fixture.sentinel); prefix.copy(output, 0, written, written + count); if (!output.subarray(count).every(byte => byte === fixture.sentinel)) throw new Error(`canonical error-progress ${mode} touched uninitialized suffix`); written += count; }
    if (written !== (grant === 0 ? 0 : fixture.expectedBytes)) throw new Error("canonical error-progress grant oracle changed initialized credit");
    checks += 1;
  }
  const parent = readFileSync(join(base, "🦀️.rs"), "utf8");
  const borrowed = readFileSync(join(base, "🧵️borrowed/🦀️.rs"), "utf8");
  const reader = readFileSync(join(base, "📖️reader/🦀️.rs"), "utf8");
  const method = (text: string, pattern: RegExp) => { const start = text.search(pattern); return start < 0 ? "" : toolJobRustBlock(text, text.indexOf("{", start))?.body ?? ""; };
  const exact = (parent: string, borrowed: string, reader: string) => {
    const indexed = method(parent, /pub fn encode_chunk\(/);
    const borrowing = method(borrowed, /fn encode_chunk</);
    const reading = method(reader, /fn encode_chunk\(/);
    const sealing = method(parent, /pub fn advance\(/);
    return parent.includes("pub struct ArtifactCanonicalJsonEncodeError") && parent.includes("pub written_bytes: usize") && parent.includes("pub reason: String")
      && indexed.includes("ArtifactCanonicalJsonEncodeError { written_bytes: written, reason }") && borrowing.includes("ArtifactCanonicalJsonEncodeError { written_bytes: written, reason }")
      && borrowing.includes("ArtifactCanonicalJsonEncodeError { written_bytes: 0, reason }")
      && reading.includes("Err(error) => { self.failed = true; error.written_bytes }") && reading.includes("self.completed_bytes.checked_add(count as u64)")
      && reading.indexOf("self.completed_bytes = completed;") >= 0 && reading.indexOf("self.completed_bytes = completed;") < reading.lastIndexOf("result")
      && sealing.includes("self.cancelled = true; encoding_error = Some(error.reason); error.written_bytes")
      && sealing.indexOf("self.transcript.update(&self.last_chunk[..self.last_length]);") >= 0 && sealing.indexOf("self.transcript.update(&self.last_chunk[..self.last_length]);") < sealing.indexOf("if let Some(error) = encoding_error { return Err(error); }")
      && sealing.indexOf("self.completed_bytes =") >= 0 && sealing.indexOf("self.completed_bytes =") < sealing.indexOf("if let Some(error) = encoding_error { return Err(error); }")
      && sealing.includes("!grant.permits_one() || self.cancelled || self.closing")
      && !/From<ArtifactCanonicalJsonEncodeError> for String/.test(parent + borrowed + reader);
  };
  if (!exact(parent, borrowed, reader)) throw new Error("canonical error-progress live encoder/reader/sealer linkage is missing");
  const mutations: [string, string, string][] = [
    [parent.replace("written_bytes: written, reason", "written_bytes: 0, reason"), borrowed, reader],
    [parent, borrowed.replace("written_bytes: written, reason", "written_bytes: 0, reason"), reader],
    [parent, borrowed, reader.replace("self.failed = true; error.written_bytes", "self.failed = true; 0")],
    [parent, borrowed, reader.replace("self.completed_bytes = completed;", "return result;")],
    [parent.replace("self.cancelled = true; encoding_error", "encoding_error"), borrowed, reader],
    [parent.replace("self.transcript.update(&self.last_chunk[..self.last_length]);", "self.transcript.update(&[]);"), borrowed, reader],
    [parent + "\nimpl From<ArtifactCanonicalJsonEncodeError> for String {}", borrowed, reader],
  ];
  for (const mutation of mutations) if (exact(...mutation)) throw new Error("canonical error-progress admitted lost initialized bytes or resumed failed authority");
  checks += 1 + mutations.length;
  return checks;
}
//#endregion 🔏️CanonicalEditSealerLaws

